import { conjugate, type ConjClass, type ConjForm } from "./classicalConjugation.ts";
import derivedData from "./verb-lexicon-index.json";

/** Per-lemma classical-conjugation data, keyed by the bare kanji (matching
 * `Token.lemma`). The overwhelming majority of this table (`derivedData`,
 * below) is generated by `scripts/build-verb-lexicon.mjs` directly from
 * Wiktionary's own classical-conjugation tables — not hand-typed — by
 * matching each word's six attested classical base forms against
 * `classicalConjugation.ts`'s own paradigm shapes. Re-run that script
 * (see its own doc for how) to pick up new words or a fresher Wiktionary
 * dump; nothing here should be hand-added for a word the script can
 * already resolve. That index holds a *list* of senses per kanji —
 * `VERB_LEXICON` is each list's leading one and `LEXICON_SENSES` the whole
 * of it.
 *
 * `okuriganaPrefix` covers words whose conventional okurigana boundary
 * starts earlier than the conjugation class's own suffix — e.g. 説ばし
 * (よろこばし) has kanji 説 covering only "よろこ", with "ば" as a fixed
 * prefix before the しく-adjective suffix proper (説+ば+しから = 説ばしから) —
 * the build script derives this the same mechanical way, by finding the
 * common leading substring that must be stripped before the remaining six
 * forms match a known paradigm.
 *
 * `fixedReading`, where present, bypasses conjugation entirely for a
 * lexicalized reading that doesn't vary with syntactic context (e.g. 曰
 * introducing reported speech is conventionally read 曰く regardless of
 * what follows it — a nominalized -aku form, not a plain conjugated verb).
 * It is the okurigana alone; `fixedFurigana` beside it is what goes over the
 * character, for the reason that field gives.
 *
 * `reading` is the word's own kanji-covered furigana reading, used only by
 * `KundokuView.ts` (kakikudashi never shows a reading for a kanji-retained
 * word). This is *not* re-derivable from `kanjidicLookup.ts`'s generic
 * kun'yomi lookup, which was tried and reverted: kanjidic only knows a
 * character's *readings*, not which one belongs to the specific verb/
 * adjective sense being conjugated here (中's kun'yomi list is
 * ["なか","うち","あた.る"] — a bare character lookup has no signal that a
 * verb use of 中 wants the third one, not the first, giving なかる instead
 * of あたる). The build script instead reads this off the very same
 * matched conjugation block that supplied `conjClass` — already
 * sense-disambiguated data, not a second guess at the same fact. It's
 * still run through the general historical-kana correction at render time
 * (`historicalKana.ts`, in `KundokuView.ts`) rather than baked in here, so
 * a fresher Wiktionary dump keeps benefiting from that index. */
export interface LexiconEntry {
  conjClass?: ConjClass;
  okuriganaPrefix?: string;
  fixedReading?: string;
  /** The furigana the `fixedReading` path draws over the character, where the
   * word divides somewhere other than `reading` divides it. 曰 is the only
   * entry that needs it and the only entry that can: `reading` is the stem the
   * *conjugating* sense takes (曰(い)ふ, the naming verb), and the fixed form
   * ends its kanji-covered part two kana later — 曰(いは)く, with only the く
   * beside the character. One entry cannot hold both boundaries in one field,
   * and stating the fixed one here is what keeps the naming use on its own.
   *
   * Read by `KundokuView.ts`'s `lexiconFurigana` under the same
   * `isNamingUse` gate that branch's okurigana already asks, so that the two
   * halves of one word cannot divide in two different places. */
  fixedFurigana?: string;
  /** Cells this entry writes **whole** — in place of `okuriganaPrefix` plus
   * the paradigm's own cell, and with nothing appended after one.
   *
   * A paradigm cell is a *stem awaiting whatever follows it*: an い-sound
   * 連用形 is 參り and becomes the converb only when a て is written after it
   * (`converbSuffix`), or when the 連用形-て switch writes one
   * (`renyouTeSuffix`). A cell stated here is the finished word instead, so
   * both of those stand down — appending to it would double a connective that
   * is already in the string, which is the same doubling those two functions
   * already refuse in front of a 而 and after にして/として.
   *
   * `PREDICATE_YI` is the only entry that has one and is what the field was
   * added for: 以てす inflects as サ変 everywhere else, but its 連用形 is written
   * 以て — the reader's ruling, *"以 in a 連用形 context is just もつて, not
   * もつてして"* — which is the ordinary converb 以て the modifier use already
   * reads, and not サ変's 以てし awaiting a connective. See that entry. */
  statedForms?: Readonly<Partial<Record<ConjForm, string>>>;
  reading?: string;
  /** **The other kun'yomi KANJIDIC2 lists for this character are other words,
   * and kanbun does not read them here.**
   *
   * A `RESIDUAL` entry does not by itself claim that. Its own doc is explicit:
   * an entry corrects a *misidentified sense*, and a misidentified sense is
   * still a real word the resolver may legitimately land on by its own
   * reading — which is why `LEXICON_SENSES` keeps the derived senses behind the
   * hand one instead of replacing them. 少 is すくなし here and 少し elsewhere;
   * 覺 is おぼゆ here and さます/さとる elsewhere; the dictionary is right about
   * all of them and only the leading answer was wrong.
   *
   * Some characters are not like that, and this field is where one says so.
   * KANJIDIC2 lists 違 as ちが.う first and たが.う fourth, and kanbun reads
   * たがふ — not sometimes, but throughout: the site glosses the character 18
   * times and never once ちが. The modern word is not a second sense this app
   * should be able to land on; it is a different language's word for the same
   * graph. The five entries carrying this are the five where that is true and
   * where KANJIDIC2 nonetheless holds the right word, so
   * `curatedWordOffKunList` — which serves 鮮, 博, 御, 索, 損, 怯, 殆 by
   * noticing that the dictionary has no such reading at all — has nothing to
   * notice.
   *
   * What it does, in `pickKun` (`reading/kanjidicLookup.ts`): narrows the
   * character's dotted kun'yomi to the ones that spell **this** word before
   * `dotted[0]` and `pickByTransitivity` are consulted, so the transitivity
   * evidence goes on separating 降**る** from 降**す** and 違**ふ** from
   * 違**へる** *inside* the word rather than choosing the word.
   *
   * **Stated per entry because the general form of it is measurably wrong.**
   * Applied to every `RESIDUAL` lemma whose reading matches one of the
   * character's kun'yomi — 24 of them — the same narrowing moves the prose
   * ratchet **+114 edits**: it drops すこ.し from 少, ゆ.く from 往, さ.める and
   * さと.る from 覺, あづか.る from 與, しら.べる from 調, every one of them a
   * word the received text does read somewhere. The claim is true of five
   * characters and false of the rest, so it is made five times. */
  soleKun?: true;
}

/** The residual: kanbun content words this app needs whose classical sense
 * Wiktionary's Japanese data can't supply the build script an answer for —
 * each commented with *why*, not just *what*, so a future Wiktionary dump
 * that starts covering one can have its entry deleted rather than
 * silently kept stale. Never overrides a lemma `derivedData` already
 * resolves correctly (see the merge below) — this is a set of gaps to
 * fill, not a correction layer sitting in front of the general mechanism
 * (that pattern was tried and reverted for historical-kana readings; the
 * lesson applies here too).
 *
 * **Two entries bend that rule, on the reader's explicit instruction, and
 * they are 反 and 空.** For both, `derivedData`'s *leading* sense is already
 * the right word — 反 かへる and 空 むなし — so by the paragraph above neither
 * should be here at all. What displaces them is not the derived data but
 * `pickByTransitivity`: 反 carries two kun pairs (そ.る / そ.らす beside
 * かえ.す / かえ.る) and the vote takes the first it meets, and 空 the same with
 * あ.く / あ.ける. The entry therefore states nothing the derived list does not
 * already say; it exists **only to carry `soleKun`**, which narrows the kun
 * list to the ones spelling this word *before* the vote is consulted, so the
 * transitivity evidence separates 反す from 反る inside the word instead of
 * choosing the word.
 *
 * That is a narrower kind of duplication than the rule was written against —
 * a correction layer in front of the *dictionary* is what it forbids, and this
 * is a flag in front of the *vote* — but it is duplication all the same, and
 * it is recorded here rather than left to be rediscovered. If `soleKun` ever
 * becomes something the build script can derive, both entries go. */
const RESIDUAL: Record<string, LexiconEntry> = {
  // 曰: two distinct uses, both needing a hand-supplied answer since
  // Wiktionary has no verb entry for 曰 at all (regardless of sense).
  // Introducing reported speech (子曰：「...」), 曰はく is a fixed -aku
  // nominalization, not a conjugating verb — `fixedReading` bypasses
  // conjugation entirely for that case (see `isNamingUse` in
  // conjugationContext.ts for how the dispatch tells the two apart). Used
  // instead as a plain naming verb (名曰軒轅, "[his] name was Xuanyuan" —
  // not a quotation), it conjugates normally as いふ/いう, the same 四段ハ行
  // class as 言ふ/謂ふ — `conjClass` covers that case. kanjidic's own
  // いわ.く is the *modern* spelling (わ, not は), so the reading is supplied
  // directly rather than deferring to it either way.
  //
  // **Where the kanji ends, for the quotative use: 曰く, and not 曰はく.** The
  // whole of いは goes over the character and only the く is written beside it,
  // which is what the received kundoku prints — 曰(いわ)く on kanbun.info, and
  // the same division in 新釈漢文大系. This app wrote 曰はく, furigana い and
  // okurigana はく, and that was the largest single disagreement with the
  // received text anywhere in the gold tier: **615 occurrences across 419 of
  // the 624 passages**, more than twice the next class. The reader's ruling is
  // to follow the received text here.
  //
  // No morpheme boundary is being crossed by the move. 曰(いは)く is the -aku
  // nominalization of いふ *whole*, so there is nothing inside いは for the
  // ruby to respect, and the only question is how much of a word with no
  // 送り仮名 of its own convention writes beside the character. Convention
  // writes one kana.
  //
  // **Two boundaries in one entry, which is why `fixedFurigana` exists.** The
  // naming use (名曰淫祀) conjugates as いふ and its stem is い, so `reading`
  // has to stay い for `conjClass` to build 曰(い)ふ / 曰(い)ひ on it, while the
  // fixed form's kanji covers いは. Moving `reading` itself instead printed
  // 曰(いは)ふ on the naming use, which is the measurement that made the second
  // field necessary rather than merely tidy.
  //
  // Measured over the 68,893 sentences of
  // `lzh_kyoto-sud-{train,dev,test}.relabeled_ext.udep_ruled.punct.rulemerged.adjfix.conllu`,
  // against a baseline re-rendered immediately before: **6,006 sentences
  // change and every one of them is 曰はく -> 曰く**, the diff being identical
  // to applying that substitution to the baseline. 6,087 occurrences move; the
  // naming verb is untouched, 曰ふ 739 and 曰ひ 40 either way.
  曰: { fixedReading: "く", fixedFurigana: "いは", conjClass: "yodan-ha", reading: "い" },

  // よろこばし ("pleased") — Wiktionary's 悦/説/悦ばしい pages are all
  // soft-redirects with no conjugation data, and 説 itself only has an
  // entry for its unrelated と.く ("to explain") sense.
  說: { conjClass: "shiku-keiyoushi", okuriganaPrefix: "ば", reading: "よろこ" },
  説: { conjClass: "shiku-keiyoushi", okuriganaPrefix: "ば", reading: "よろこ" },
  悦: { conjClass: "shiku-keiyoushi", okuriganaPrefix: "ば", reading: "よろこ" },

  // 慍る (四段ラ行, "to be resentful, to take offence") — no modern reflex in
  // Wiktionary at all; this sense didn't survive into contemporary Japanese
  // vocabulary, so the word has to be stated here either way.
  //
  // **いきどほる and not うらむ.** The received kundoku of 人不知而不慍 is
  // 人知らずして慍(いきどほ)らず — kanbun.info prints いきどお over the
  // character — and every other 慍 in the gold is the same word: 慍見 (子路
  // 慍りて見ゆ), 舞斯慍, 慍于群小. うらむ is 怨/恨's word, and reading 慍 with
  // it made the two indistinguishable on the page. KANJIDIC2 lists いか.る,
  // いか.り and うら.む for the character and not いきどほる at all, which is
  // why the reading is stated here rather than left to the generic kun lookup.
  //
  // **Measured** over `lzh_kyoto-sud-{train,dev,test}.…adjfix`: 慍 is 12
  // tokens, 9 of them predicates (VERB or a `Conv`-tagged ADV) and 3 nominal
  // (無慍色 and the like), and every predicate use is this word.
  慍: { conjClass: "yodan-ra", reading: "いきどほ" },

  // 愛す (サ変, "to love, to hold dear") — the build script's leading answer
  // for 愛 is 愛づ (下二段ダ行, めづ), which is a real Japanese word and not the
  // one kanbun reads: めづ is "to find charming, to admire", and the object of
  // a classical 愛 is a person. 愛人 is 人を愛す — 仁者愛人, 君子學道則愛人,
  // 愛人者人恆愛之 — and 節用而愛人 is 用を節して人を愛し, which is what
  // kanbun.info prints for 學而 5. Rendered over the whole gold, 愛 printed
  // 愛づ/愛で in the great majority of its 270 predicate uses, every one of them
  // this sense.
  //
  // サ変 and not the derived 四段サ行, because that is the paradigm this app
  // already gives a 漢語 read on'yomi as a predicate: a VERB with no lexicon
  // entry of its own reaches `onyomiPairReading`'s サ変 and prints 忠す, 信す,
  // 大破す. 愛 differs from those only in having an entry, and the entry should
  // not put it in a different conjugation from its own neighbours.
  //
  // めづ, いとし and the rest survive behind this in `LEXICON_SENSES` for the
  // menu and for a hand-picked reading.
  //
  // **This entry reached only the 愛 with no object until the vote was taught
  // to leave it alone.** KANJIDIC2's transitivity check, asked about a 愛 that
  // governs one, answers め.でる over いと.しい — and reporting that as a
  // decision set `beatsLexicon` and stood this entry down, so 汎愛眾 (學而 6)
  // printed ひろく眾を愛づ where the received kundoku is 汎く衆を愛して. The
  // vote grades *kun'yomi* of the character, and 愛す is a 漢語 no okurigana
  // of 愛 spells, so it was never a candidate and the answer refuted nothing;
  // `curatedOnyomiWord` in `reading/kanjidicLookup.ts` is where that is stated
  // and measured. **149** of 愛's 158 object-taking gold VERB tokens were
  // reading め and now read あい.
  愛: { conjClass: "sa-hen", reading: "あい" },

  // 省みる (上一段, "to look back on, to examine oneself") — Wiktionary's
  // derived answer for this kanji is はぶく ("to omit, to cut down"), a real
  // word of the character and the wrong one for the sense kanbun leans on:
  // 吾日三省吾身 is わが身を省みる, 見不賢而內自省 is 內にみづから省みる, 內省不疚
  // and 昏定而晨省 the same word again. kanbun.info prints かえり over the
  // character in 學而 4.
  //
  // **Both senses are live in the gold and this one is the leading half.** Of
  // the 43 sentences where 省 is a predicate (VERB, or ADV with a verbal
  // xpos), roughly 22 are this word — the reflexive and inspecting uses,
  // including every canonical passage — against roughly 18 for はぶく (省刑罰,
  // 省婦事, 省醴, 當去奢省費, 陳器之道…省納之). That is not a landslide, and it
  // is why はぶく is not deleted: the build script's entry survives behind this
  // one in `LEXICON_SENSES`, where the furigana menu offers it and a
  // hand-picked reading reaches it. What changes is only which of the two the
  // page writes unasked, and the reflexive sense is the commoner and the one
  // the received readings want.
  //
  // かへり + みる, the same split 用 takes as もち + ゐる: the class supplies る
  // and the row's own vowel comes from the prefix, since 上一段 never surfaces
  // its consonant in the suffix (see `classicalConjugation.ts`).
  省: { conjClass: "kami-ichidan", okuriganaPrefix: "み", reading: "かへり" },

  // 謂ふ ("to call/say X") — "謂う" is a soft-redirect with no data; same
  // は行四段 row as 言ふ, which does have a full attested table.
  謂: { conjClass: "yodan-ha", reading: "い" },

  // 為す ("to do/make") — "為す"/"爲す" are soft-redirects; さ変 is the
  // well-known irregular class for this word regardless.
  //
  // **爲 is two verbs and this entry is one of them, and the second could not be
  // made to pay. Measured, and not to be tried again without new evidence.**
  // kanbun.info reads a 爲 that takes on a role as 四段ラ行 為る — 其爲人也 is
  // 其の人と**為り**や (論語 1.2, again at 7.19), 三仕爲令尹 令尹と**為り**て,
  // 女爲君子儒 君子の儒と**為れ**, 子游爲武城宰 武城の宰と**為る** — against the
  // なす this entry gives them all. The split is not "become" against "make":
  // 執輿者爲誰 has no object at all and the site still reads 誰と**為す**, as it
  // reads 斯爲美 斯を美と**為す** and 和爲貴 和を貴しと**為す**. What separates
  // them is a **role** complement from an identifying one.
  //
  // Built as a `lexiconEntryFor` arm beside `comparisonLexiconEntry` — 爲 with a
  // `comp:pred` child, `yodan-ra` + な — and narrowed five ways, each measured
  // over the whole corpus against the tree rendered in the same process:
  //
  //  | gate on the `comp:pred` child | gold | parser |
  //  |---|---|---|
  //  | any complement                | +1 | +75 |
  //  | 爲's own xpos `v,動詞,存在`     | +1 | +77 |
  //  | …and 爲 governs no `comp:obj`  | +1 | +72 |
  //  | child is a 人-class noun       | **−2** | +33 |
  //  | child is `n,名詞,人,役割`       | **−3** | +24 |
  //
  // **The gold tier agrees with the rule and the parser tier refuses it**, and
  // the reason is visible in the regressions: every one is an AをBと為す —
  // 以三軍と為す, 五家を軌と為す, 黄帝を有熊と為し, 河間王と為し — where the A is
  // introduced by 以 or tagged `subj`, so 爲 has no `comp:obj` to be told apart
  // by. The narrower the gate the better gold reads and the worse the parser
  // tier does, which is the signature of a rule that is right about the language
  // and dependent on annotation the parser does not supply. Net alignment is
  // worse in all five, so none ships.
  //
  // `overrides.json`'s 爲 たり does not reach these either: it is gated on
  // `contextPos: ["VERB"]` with the *token's own* `contextDep` `comp:pred`/ROOT,
  // and a copular 爲 is tagged **AUX** with the `comp:pred` on its child.
  爲: { conjClass: "sa-hen", reading: "な" },
  為: { conjClass: "sa-hen", reading: "な" },

  // 成る ("to become") — a genuine homograph the build script can't resolve
  // on its own: 成/為 are *both* attested kanji spellings of two different
  // kana-headword verbs, なる ("to become", 四段ラ行) and なす ("to do/make",
  // 四段サ行 — な+す, unrelated to 為す above despite the same kanji), each
  // only reachable via its kana entry's own "kanji"-tagged alternate forms,
  // not a direct kanji-headword page of its own. Whichever entry the build
  // script happens to reach first for a given kanji wins by construction
  // (see its own doc) — for 成 that was なす, giving the wrong sense for
  // 成而聰明 ("becoming wise", 成る, not "making [something]"). 為 doesn't
  // need its own residual line for this, since it already has the sa-hen
  // one above (為す, not なる, is the standard kundoku sense there).
  成: { conjClass: "yodan-ra", reading: "な" },

  // **來/来 is deliberately absent, and that is the reader's ruling.**
  //
  // It stood here as き + an `okuriganaPrefix` of た, showing the stem's second
  // kana beside the character (来たる) where the build script's own derived
  // sense folds it into the furigana (来る read きたる) — a *typesetting*
  // convention difference, not a conjugation-class disagreement, the class
  // being 四段ラ行 either way. The received text folds it: kanbun.info writes
  // 来る and 来らんとす, and measured over that corpus the visible division read
  // 41 edits further from the site across 46 passages. The reader has settled
  // it the site's way.
  //
  // So there is nothing left for an entry here to say. The derived sense is
  // already きた + 四段ラ行, and a `RESIDUAL` duplicate of it is not merely
  // redundant but harmful: `RESIDUAL` is *prepended* to a kanji's derived
  // senses, so the copy shadowed the derived one in `LEXICON_SENSES` and
  // `attestedSenseByModernSpelling` stopped answering for 來 and 来 at all —
  // visible in this file's own census as verbLexicon 192 -> 190.
  //
  // **What was actually wrong with 來 was the reading, and it is fixed
  // elsewhere.** KANJIDIC2 lists く.る first — 来る, カ変, the verb of the
  // modern language — and the transitivity vote took it, reported
  // `transitivitySelected`, and stood this entry down whatever it said; the
  // panels then inflected く- as 四段 and wrote 來り for 來たり, which spelled
  // out in kana is the くりて the reader found. That is fixed where it arose,
  // in `SUPPLEMENTARY_KUN` (kanjidicLookup.ts), which names きた.る as the word
  // this character is in kanbun and keeps the vote off it.

  // **主とす and 友とす — a role noun predicated with と + サ変**, which is how
  // kanbun reads a noun used as a verb: 主忠信、無友不如己者 is 忠信を主とし、己に
  // 如かざる者を友とすること無かれ.
  //
  // KANJIDIC2 gives both characters only *undotted* kun — 主 ぬし/おも/あるじ,
  // 友 とも — so a token tagged VERB resolved to a bare noun with no okurigana
  // and no class, and both panels printed the character with nothing after it:
  // 忠信を主。…者友。 That is the fault; these two entries are the fix, and the
  // reason they are two entries rather than a rule is measured.
  //
  // **The rule was tried and it reads worse.** "A VERB whose every KANJIDIC2
  // kun is undotted" is **4,120 tokens over 525 characters** in the gold, and
  // it is not the class "a noun used as a verb": it also holds every character
  // whose kanbun *verb* is simply missing from a dictionary of the modern
  // language — 道 いふ, 喪 うしなふ, 衣 きる, 徵 めす, 涉 わたる — where とす is
  // nonsense. Applied to the whole class it read **+21 gold / +442 parser**
  // edits worse against kanbun.info; narrowed to a `comp:obj`-bearing token it
  // was still +96 on the parser tier for −6 on the gold, and the per-character
  // damage was 道 +22, 徵 +18, 縱 +16, 喪 +13 against 友 −14 and 主 −5. No
  // feature of the tree separates the two populations, the treebank's own xpos
  // subcategory included (`v,動詞,行為,役割`, which holds 主, is +9 over 20
  // passages).
  //
  // So it is a missing *word*, not a missing rule, and the words are named
  // here one at a time as the reader settles them. In the gold tier every
  // verbal 主 is 主とす (rongo0108, rongo0316, rongo0924, 論語 12.10) and every
  // verbal 友 is 友とす; the parser tier's 主 are mostly the plain noun and are
  // not this entry's to answer for, `usesLexiconEntry` admitting only a VERB.
  // The on'yomi しゅ is the received reading of the predicated character —
  // 忠信を主(しゅ)とし — and an on'yomi in this table is not new: 仁 じん sits
  // below on the same footing.
  主: { conjClass: "sa-hen", okuriganaPrefix: "と", reading: "しゆ" },
  友: { conjClass: "sa-hen", okuriganaPrefix: "と", reading: "とも" },

  // **莫し and 毋し — the same word 無 already has here**, ク活用 な, and added
  // because the two characters now reach the page where they did not before.
  // `POSTPOSE_PREDICATE_NEGATION_LEMMAS` (depClassification.ts) moves a
  // preverbal negative existential to where kundoku reads it, and 莫/毋 join
  // that set **by the reading and not by the tag**: this treebank files them
  // under 勿's 禁止 class (`v,副詞,否定,禁止`), but 勿 writes ず onto its head's
  // 未然形 while these realise a predicate of their own — 莫知其鄉 is
  // 其の鄉を知る**莫し**, not 知らず. With the movement right and no entry, they
  // printed as a bare character with nothing after them (其の極を知る莫), one
  // edit each against the received text.
  //
  // One entry serves both readings the received text writes: 莫 as the 終止形
  // 莫し and 毋 as the 命令形 毋かれ — 己に如かざる者を友とする毋かれ (論語 9.24)
  // — are the same ク活用 word inflected for where it stands, which is exactly
  // what a class in this table is for.
  //
  // **罔 and 靡 are deliberately not here**, though the same set moves them.
  // 罔 has a second kanbun reading that a lemma-keyed entry cannot tell apart —
  // 學而不思則罔 is 學びて思はざれば則ち罔し, くらし and not なし — and 靡 already
  // holds なび (四段, 靡く), a real word this would displace for 3 tokens.
  // Both are left reading as they do until the reader settles them.
  莫: { conjClass: "ku-keiyoushi", reading: "な" },
  毋: { conjClass: "ku-keiyoushi", reading: "な" },

  // 往ぬ ("to go/depart") — soft-redirect, no data; classical grammar has
  // exactly two ナ変 verbs (死ぬ/往ぬ), 死 already resolves via Wiktionary.
  往: { conjClass: "na-hen", reading: "い" },

  // 取る ("to take") — itself a soft-redirect with no data; only its modern
  // compounds (取り戻す etc.) have full entries, none in the plain row.
  取: { conjClass: "yodan-ra", reading: "と" },

  // 種う ("to plant", 種樹 "to plant trees") — ワ行下二段, the same word as
  // 植う and spelled with it in modern Japanese (植える). Wiktionary files the
  // word under 植 and has no verb entry for 種 at all, so the build script
  // derives 植 correctly and 種 not at all; `SUPPLEMENTARY_KUN` in
  // `kanjidicLookup.ts` supplies the reading う (KANJIDIC2 lists only the
  // noun たね and the on'yomi), but a reading with no class conjugates
  // nowhere — 種樹 came out 樹を種, the bare character with no ending.
  //
  // The class could not even be *written* here until ワ行下二段 existed:
  // `readingResolver.ts` refuses to derive any あ-row -eru mechanically,
  // because 得る/見える/植える have collapsed onto one え in modern spelling,
  // and ゑ is exactly the distinction that recovers this one — 種ゑて, not
  // 種えて.
  種: { conjClass: "shimo-nidan-wa", reading: "う" },

  // 貰ふ ("to receive", 需何藥 "what medicine [do I] get") — ハ行四段:
  // もらは/もらひ/もらふ/もらふ/もらへ. Chosen by the reader, who was asked;
  // it is not a dictionary's claim about 需 and no source attests it. Every
  // other entry in this table corrects a *sense* Wiktionary got wrong for a
  // word it does hold; this one is a word the reader has assigned to a
  // character, and it is here for the same mechanical reason 種 above is: the
  // reading is supplied by `SUPPLEMENTARY_KUN` in `kanjidicLookup.ts`
  // (KANJIDIC2's entry for 需 lists no kun'yomi whatever, only ジュ), and a
  // reading with no class conjugates nowhere — 需 printed もらふ in every
  // position, 未然形 and 已然形 alike. That file's own doc carries the rest of
  // the argument, including why both tables are needed rather than either
  // one.
  需: { conjClass: "yodan-ha", reading: "もら" },

  // 仁なり ("to be benevolent") — ナリ活用形容動詞. This parser tags a stative
  // predicate `Degree=Pos` — VERB up to 0.3.1, **ADJ** from 0.3.2, both of
  // which `usesLexiconEntry` admits — and 仁 is one of the commonest in the
  // corpus (仁者, 仁人, 君子仁也), but KANJIDIC gives 仁 *no kun'yomi at all*:
  // it is a Sino-Japanese abstract noun, read on'yomi and predicated with なり.
  // With no reading to inflect, 仁者 came out 仁もの where kundoku wants
  // 仁なる者 — the 連体形 rule fired correctly and had no paradigm to select
  // from. (This paragraph once closed "賢 needs nothing here because it has a
  // real kun'yomi (さかし) and conjugates as シク活用 already", which was true
  // of the mechanism and wrong about the word — see 賢's own entry below, which
  // is the addition the next paragraph anticipated.)
  //
  // Only 仁. The same shape covers 義/禮/智/信 and every other kun-less virtue
  // noun, and each is a separate claim about how that word is read
  // predicatively rather than one rule — listed here so the next one is an
  // addition, not a rediscovery.
  仁: { conjClass: "nari-keiyoudoushi", reading: "じん" },

  // 賢なり ("to be worthy, to be of ability") — ナリ活用形容動詞, and **the
  // addition 仁's note above says the next one will be**. 賢哉囘也 is
  // 賢**なる**かな囘や, which is what 論語 prints; the app wrote 賢**しき**かな,
  // and the reader has ruled the received reading.
  //
  // **The one thing that had to be overturned is 仁's own aside**, that 賢 needs
  // no entry *because* it has a real kun. It has one — さかし, KANJIDIC's
  // かしこ.い modernised — and the build script derives `shiku-keiyoushi` さか
  // from it, so 賢 conjugated all along and conjugated as the wrong word.
  // さかし is "clever, shrewd" and carries the sense 小賢しい still has; the 賢 of
  // 賢者・賢人・不賢 is the Sino-Japanese abstract けん, predicated with なり
  // exactly as 仁 is. Having a kun is therefore not evidence *against* an entry
  // here — it decides which of two real words the character spells, which is
  // what most of this table is for (說, 戰, 出, 覺, 適).
  //
  // **Measured** over
  // `lzh_kyoto-sud-{train,dev,test}.relabeled_ext.udep_ruled.punct.rulemerged.adjfix.conllu`.
  // 賢 is **375** tokens: **ADJ 229** — `mod` 142, `comp:obj` 41, `root` 35, and
  // 12 more on `conj:coord`/`subj`/`parataxis`/`comp:obl` — **NOUN 130**,
  // **PROPN 13** (董賢, a Han courtier) and **ADV 3**. Only the ADJ reach this
  // table (`usesLexiconEntry`), and every one of the 229 carries the single xpos
  // `v,動詞,描写,態度`: there is no second adjective sense in the corpus for an
  // entry keyed on the lemma to run over, which is the thing 鮮's entry below
  // has to give three tokens away to.
  //
  // Rendered through `computeReadingOrder` + `generateKakikudashi` over the
  // whole gold, **149** of the 68,893 sentences change, and every edit is one
  // word swapped for the other on the same slot: しき→なる 83, し→なり 34,
  // しく→に 16, しか→な 12 (賢しからず -> 賢ならず). 賢哉回也 賢しきかな ->
  // 賢**なる**かな; 見不賢而內自省 賢しからざる -> 賢**なら**ざる; 仲尼豈賢於子乎
  // 賢しきか -> 賢**なる**か.
  //
  // **Some of the 149 landed on a defect that was not this entry's, and it has
  // since been fixed.** Where an assertive 也 closed a clause whose predicate is
  // ナリ活用, `repeatsPredicateCopula` suppressed the particle's own なり
  // (君子仁也 is 君子仁なり, not 君子仁なりなり) while `decideConjForm` went on
  // selecting the 連体形 the particle asked for — so the two together wrote a
  // bare 連体形 and no copula at all, and 君子仁也 rendered 君子仁**なる** against
  // what that function's own doc says it writes. It was pre-existing rather than
  // a consequence of this entry; adding 賢 merely made it visible in more
  // sentences. `decideConjForm`'s 也 branch now asks `repeatsPredicateCopula`
  // itself and returns 終止形 where the copula is being suppressed, so the two
  // read one predicate and cannot disagree. 17 sentences were affected in all
  // (仁 7, 賢 5, 大 4, 暴 1).
  賢: { conjClass: "nari-keiyoudoushi", reading: "けん" },

  // 大なり ("to be great") — ナリ活用形容動詞, the second of the reader's pair
  // and the one whose evidence had to be weighed rather than counted.
  // 大哉堯之爲君也 is 大**なる**かな, which `SENTENCE_FINAL_PARTICLES`' own 哉
  // note has quoted since that rule was written; the app wrote 大**き**かな.
  //
  // **What it was reading instead was 多し.** The build script's derived entry
  // is `ku-keiyoushi` おお, from KANJIDIC's おお.きい split at the dot — so the
  // paradigm it inflected was 大し / 大き / 大く, and 大し is おほし, the word
  // modern Japanese writes 多し. There is no ク活用 adjective 大し. The classical
  // word is 大なり / 大いなり, ナリ活用 throughout, and this entry states it.
  //
  // **Measured** over the same gold. 大 is **2,669** tokens: **ADJ 2,025** —
  // `mod` 1,817, `comp:obj` 67, `root` 51, `flat@vv` 46, `comp:pred` 20, and 24
  // more — **ADV 616**, **NOUN 25**, **PROPN 3**. Rendered both ways, **723** of
  // the 68,893 sentences change: 終止形 し→なり 209, 連体形 き→なる 86,
  // かな-frame か→な 8, and 連用形 く→に 399. 大哉孔子 大きかな -> 大**なる**かな;
  // 賢者識其大者 その大**き**もの -> その大**なる**もの; 無乃大簡乎 大**く**簡ぶ ->
  // 大**に**簡ぶ.
  //
  // **The reading is おほ + `okuriganaPrefix` "い", and it took a mechanism to
  // write.** KANJIDIC2 attests the very division, listing `-おお.いに` among 大's
  // kun, and it is what kundoku prints throughout: 大いなるかな, その大いなるもの,
  // 大いに簡ぶ. Three spellings were tried through the pipeline and this is the
  // one the other two were standing in for:
  //
  //  - **だい**, which stood here while the prefix could not be written — a
  //    Sino-Japanese abstract predicated with なり, the same shape 仁 above has.
  //    The paradigm is identical either way, which is why it was a safe
  //    placeholder and why swapping it moves no form, only the spelling: it
  //    printed 大(だい)に across the adverbials where おほいに is the received
  //    reading, and 大なるかな where 論語 editions print 大いなるかな.
  //  - **おほい, no prefix**, which conjugates cleanly (the prefix was what
  //    broke, not the reading) and puts the い in the *furigana* — 大(おほい)なる
  //    — where the convention writes it beside the character.
  //  - **おほ + い**, which is here. What blocked it: an ADV 大 with
  //    `VerbForm=Conv` — all **616** of the gold ADV tokens carry it — is
  //    admitted to the lexicon by `isConverbUse`, and for it the resolver's
  //    `adverbialCopulaEnding` answers いに and sets `beatsLexicon`, after which
  //    `syntheticLexiconEntry` rebuilds an entry from the *reading* alone and a
  //    synthesized entry carries no `okuriganaPrefix` by design.
  //    `attestedSense` is what recovers the real one, and it was comparing
  //    `conjugatedOkurigana(sense, "shuushi")` — いなり — against an okurigana
  //    the resolver had written in the 連用形. No sense matched, and the い was
  //    dropped. The resolver now reports the form it wrote (`okuriganaForm` on
  //    `ResolvedReading`) and the match is made in it; the note on
  //    `pinnedKeiyoudoushi` naming this exact failure is the precedent.
  //
  // **Measured**, against a baseline re-rendered immediately before, over
  // `lzh_kyoto-sud-{train,dev,test}.relabeled_ext.udep_ruled.punct.rulemerged.adjfix.conllu`:
  // **691** of the 68,893 sentences change and every change is the same い —
  // **402** 大いに, **205** 大いなり, **91** 大いなる, **8** 大いなら — with the
  // reading order byte-identical. 無乃大簡乎 大**に**簡ぶ -> 大**いに**簡ぶ;
  // 大哉堯之爲君也 大**なる**かな -> 大**いなる**かな; 賢者識其大者 その大なるもの ->
  // その大**いなる**もの. **381** of the 402 adverbials are the ones the
  // `okuriganaForm` report carries — without it they print 大(おほ)に, which is a
  // reading of nothing — and the other 21 reach the prefix through the plain
  // `VERB_LEXICON` path, which never lost it.
  //
  // **What the ナリ entry costs, measured and not hidden.** An ADV 大 standing
  // immediately in front of the nominal it governs is a Sino-Japanese binom
  // being read as a modifier plus its head, and there it writes a 連用形 where
  // the word wants none. **16** gold tokens are in that position and **13** of
  // them take the ending: 喪服大記 comes out 喪の服大**いに**記なり, 大昏為大 comes
  // out 大**いに**昏大いなり為す. The annotation is right — 大 does modify 記 —
  // and the gap is `findCompoundSpans`', which holds 大學 (食三老五更於大學 reads
  // 大學より食ふ, with no ending at all) and not 大記; the entry is not narrowed
  // to hide it, and nothing here can draw the line, since the lemma alone
  // cannot say which 大 begins a lexicalized word.
  大: { conjClass: "nari-keiyoudoushi", okuriganaPrefix: "い", reading: "おほ" },

  // 少なし ("few") — modern 少ない has no classical table (its "ない" is a
  // separate modern negative-adjective suffix, not this word's own okurigana).
  //
  // な is an `okuriganaPrefix` and not part of the reading, by this file's own
  // criterion for one: the conventional okurigana boundary starts earlier than
  // ク活用's own suffix, exactly as 説ばし's does. 少(すく)なし is how kundoku
  // prints it — 少なき, 少なく — where a bare すくな reading gave 少し and 少く,
  // with the な swallowed into the furigana and the okurigana no longer the
  // word's own. Nothing pinned the old boundary; 少 is 233 gold tokens.
  少: { conjClass: "ku-keiyoushi", okuriganaPrefix: "な", reading: "すく" },

  // 鮮なし ("few, rare") — the same word 少 is, and entered the same way, な
  // and all, so the two cannot render differently. KANJIDIC's sole kun for 鮮 is あざ.やか,
  // which is not wrong about Japanese and is wrong about kanbun: it is a
  // dictionary of the modern language, and the classical "few" sense simply is
  // not in it, so the resolver had nothing better to offer than あざ + やか —
  // a stem with no paradigm, which left 鮮 uninflected wherever a form was
  // called for (孝弟而好犯上者鮮矣 came out 好む者は鮮やか、 with the 連用形
  // the chain had already decided for it invisible).
  //
  // **The gold says which word it is, 16 times out of 20.** Over
  // `lzh_kyoto-sud-{train,dev,test}.relabeled_ext.udep_ruled.punct.rulemerged.
  // adjfix.conllu`, every 鮮 in the corpus: **16** ADJ `v,動詞,描写,量` — the
  // *quantity* class, which is すくなし — 以約失之者鮮矣 · 民鮮久矣 ·
  // 知德者鮮矣 · 巧言令色，鮮矣仁 · 不亦鮮乎; **3** ADJ `v,動詞,描写,形質`,
  // which is the あざやか "fresh" sense — 鮮魚曰脡祭 · 鮮肥屬時禁 ·
  // 紅妝白日鮮; and **1** NOUN (冬宜鮮、羽). The reader has ruled すくなし.
  //
  // **It costs those 3, and nothing here can save them.** 鮮魚 will read
  // 鮮なき魚 where it wants 鮮やかなる魚. The two senses are separated in the
  // *xpos* — 量 against 形質 — and this table is keyed on the lemma alone, so
  // the distinction cannot be drawn from here at all. A reading override on
  // the xpos would be the place for it if the three ever matter; they are 15%
  // of the character and none of them is a predicate a form is asked of.
  鮮: { conjClass: "ku-keiyoushi", okuriganaPrefix: "な", reading: "すく" },

  // ---------------------------------------------------------------------------
  // **The wrong kun: a modern word where kanbun reads another.**
  //
  // Ten characters, one class. Each reads on the page as the word modern
  // Japanese gives it rather than the word the received text reads, and in
  // every case the fault is upstream of anything this app decides: KANJIDIC2 is
  // a dictionary of the modern language, its kun'yomi are listed in modern
  // order, and `pickKun` takes the first one. 違 comes out ちがふ where the
  // 論語 reads たがふ; 降 おりる where it reads くだる; 索 さくす — an on'yomi,
  // for want of any kun at all — where it reads もとむ.
  //
  // **The authority is kanbun.info's ruby**, the reader's ruling: where a
  // reading of ours disagrees with what the site prints over the character, the
  // site is right. Each entry below carries the site's own gloss count and a
  // received line to read it in, and the ten together are **138** of the
  // glossed occurrences `tests/kanbunInfoRuby.test.ts` counts wrong.
  //
  // **A general rule was looked for first and does not exist.** Three were
  // measured over the site's 3,407 passages and all three are in the record:
  //
  //  - *Prefer the lexicon's own reading to KANJIDIC2's kun* — 541 characters /
  //    1,865 occurrences against 535 / 1,795, **worse**. It fixes 鮮, 御, 博 and
  //    breaks 獲, 怒, 率, 更, 被 and seven more. A derived entry is Wiktionary's
  //    leading *modern* sense, which is no better evidence about a kanbun
  //    character than the dictionary already asked.
  //  - *Prefer a hand-stated `RESIDUAL` reading* — 533 / 1,778, **better, and
  //    shipped**: see `curatedWordOffKunList` (kanjidicLookup.ts) and the branch
  //    it gates in `readingResolver.ts`. That is what makes an entry here state
  //    the character's *reading* and not only its paradigm, and it is why these
  //    ten are entries rather than override lines.
  //  - *Take the classical sense the derived list ranks below the modern one* —
  //    no rule to state. The right word is somewhere in `LEXICON_SENSES` for
  //    違 (たが, 3rd), 割 (さ, 2nd) and 倦 (う, 2nd), and is absent for 降, 速,
  //    殆, 索, 操, 均, 環, 御. Nothing in the data says which rank is the kanbun
  //    one, and a rule keyed on the rank is a rule keyed on nothing.
  //
  // So they are named one at a time, which is what the last round of this
  // concluded too (a rule keyed on KANJIDIC2's kun *shape* was 4,120 tokens and
  // measured +21/+442 worse). What each entry claims is a word, with the
  // received line that shows its paradigm.
  // ---------------------------------------------------------------------------

  // 違ふ ("to differ from, to go against") — 四段ハ行, and **the clearest of the
  // ten**: the site glosses 違 たが **18** times and さ 4, never ちが, and 14 of
  // the 22 are gold passages where a difference is ours by construction.
  // 孟懿子問孝 is 違ふこと無かれ; 吾與回言終日不違 吾、回と言ふこと終日、違はざる;
  // 其心三月不違仁 其の心三月仁に違はず; 雖違眾 衆に違ふと雖も.
  //
  // KANJIDIC2 lists both words — ちが.う, ちが.い, ちが.える, たが.う, たが.える
  // — and lists the modern one first, so `dotted[0]` took ちが and, both being
  // transitive/intransitive pairs, `pickByTransitivity` went on choosing
  // between ちが.う and ちが.える and reported `transitivitySelected`, which
  // stands this table down altogether. The character read ちがへる under a
  // たがふ paradigm. `curatedKunWord` is what narrows the vote to this word's
  // own two kun'yomi, so the object evidence still separates 違ふ from 違へる
  // inside it; see it for why narrowing and not yielding.
  違: { conjClass: "yodan-ha", reading: "たが", soleKun: true },

  // 降る/降す ("to descend; to bring down, to subdue") — 四段ラ行, with the
  // 四段サ行 降す the vote picks where there is an object. The site glosses 降
  // くだ **31** times and こう once, never お. 青陽降居江水 is 青陽は降りて
  // 江水に居る; 軍遂降漢 軍遂に漢に降る; 不降其志 其の志を降さず;
  // 燕既盡降齊城 燕既に尽く斉の城を降す.
  //
  // KANJIDIC2 has お.りる/お.ろす first and くだ.る/くだ.す fourth — two pairs,
  // of which the modern one leads. The military sense that fills these texts is
  // the second pair throughout, and both members of it are wanted: `pickKun`
  // narrows to くだ and the vote goes on choosing る or す. The rain sense
  // (ふ.る, 雨降る) is a third word and is not what any of the 32 tokens is.
  降: { conjClass: "yodan-ra", reading: "くだ", soleKun: true },

  // 速やかなり ("prompt, swift") — ナリ活用形容動詞, the reading すみ with やか
  // as an `okuriganaPrefix` on the model of 暴 にはか. The site glosses 速 すみ
  // **13** times and そく once, never はや. 無欲速 is 速やかならんことを欲する
  // 無かれ; 退而不可追者速而不可及也 速やかにして及ぶ可からざればなり;
  // 兵之情主速 兵の情は速やかなるを主とす; 輕進速退 軽く進み速やかに退き.
  //
  // KANJIDIC2 lists はや.い, はや-, はや.める, すみ.やか, and the app took the
  // first: 速 read はやし, a real word and the wrong one here. **The prefix is
  // the whole of what makes this a 形容動詞 rather than a ク活用 adjective** —
  // すみ + やか + なり — and it is KANJIDIC2's own division, dot and all.
  速: { conjClass: "nari-keiyoudoushi", okuriganaPrefix: "やか", reading: "すみ", soleKun: true },

  // 殆ふし ("perilous") — ク活用, the reading あや with ふ as an
  // `okuriganaPrefix`, which is 危ふし written with this character. The site
  // glosses 殆 あや **13** times out of 13. 思而不學則殆 is 思ひて学ばざれば
  // 則ち殆ふし; 多見殆 多く見て殆ふきを闕き; 知止所以不殆 止まる所を知るは
  // 殆ふからざる所以なり; 曰殆哉 殆ふいかな.
  //
  // KANJIDIC2's list is ほとほと, ほとん.ど, あやうい — the adverb "almost"
  // first and this word last, undotted, so it is not even a candidate the
  // paradigm rules can inflect. The "almost" sense is a real reading of the
  // character and is not what these thirteen are; where it is wanted the
  // furigana menu still offers it.
  殆: { conjClass: "ku-keiyoushi", okuriganaPrefix: "ふ", reading: "あや" },

  // 割く ("to cut apart, to cede") — 四段カ行. The site glosses 割 さ **8**
  // times and き once, never わ. 割雞焉用牛刀 is 鶏を割くに焉くんぞ牛刀を用ゐん;
  // 大制不割 大制は割かず; 聖人方而不割 聖人は方にして割かず; 操刀必割
  // 刀を操れば必ず割く.
  //
  // KANJIDIC2 has わ.る, わり, わ.り, わ.れる, さ.く: the modern 割る first and
  // this word last. Wiktionary's own data holds it too — `LEXICON_SENSES` has
  // 四段カ行 さ as 割's second sense — which is what nothing in the derived data
  // can say is the kanbun one, and what this entry says.
  割: { conjClass: "yodan-ka", reading: "さ", soleKun: true },

  // 損す ("to diminish, to lose") — サ変, a 漢語 like 愛す and entered for the
  // same reason. The site glosses 損 そん **13** times out of 13. 或損之而益 is
  // 或いは之を損して益し; 損之又損 之を損して又損し; 天之道損有餘而補不足
  // 天の道は余り有るを損して足らざるを補ふ. The 連用形 the received text prints
  // is 損**し**, which is サ変 and not ザ変.
  //
  // KANJIDIC2 gives only そこ.なう/そこ.ねる, the modern transitive 損なふ, so
  // the vote had two candidates and neither was the word. Reaching the page
  // needs `curatedWordOffKunList`, which is what an on'yomi entry has always
  // needed here (see `curatedOnyomiWord` for the vote's half of it).
  損: { conjClass: "sa-hen", reading: "そん" },

  // 索む ("to seek out") — 下二段マ行. The site glosses 索 もと **11** times out
  // of 11. 校之以計而索其情 is 之を校ぶるに計を以てして其の情を索む;
  // 必索敵人之間來間我者 必ず敵人の間の来りて我を間する者を索め;
  // 農戰不外索權 農戦は外に権を索めず.
  //
  // KANJIDIC2 gives 索 **no kun'yomi at all**, so the character fell to the
  // on'yomi rule and printed さくす — which is a reading of 索引 and not of
  // this. 封, 謁 and 療 are the characters that rule is right about; this one it
  // was wrong about for want of anything else to say.
  索: { conjClass: "shimo-nidan-ma", reading: "もと" },

  // 怯なり ("timid, cowardly") — ナリ活用形容動詞, a 漢語 predicated with なり
  // on the model of 仁 and 賢 above. The site glosses 怯 きょう **8** times and
  // おそ once, never ひる. 智而心怯者 is 智にして心怯なる者有り;
  // 外勇而內怯者 外勇にして内怯なる者有り; 怯生於勇 怯は勇に生ず (the bare
  // noun, which takes no ending and is not what this entry is for);
  // 鮑叔不以我爲怯 鮑叔以て怯と為さず.
  //
  // **The reading is けふ and not きよう**, which is this character's on'yomi in
  // 歴史的仮名遣い — the spelling `candidateReadings` itself offers for 怯, and
  // the same fold that writes 業 げふ and 協 けふ. The table is historical
  // throughout; the site prints modern kana and the ruby comparison folds ours
  // to it (けふ -> けう -> きよう), so the two agree.
  //
  // KANJIDIC2's ひる.む, おび.える, おそ.れる are all verbs, and the character
  // here is not a verb at all.
  怯: { conjClass: "nari-keiyoudoushi", reading: "けふ" },

  // 罷む ("to cease, to break off") — 下二段マ行. The site glosses 罷 や **6**
  // times and つか 2, never まか. 晉師聞之爲罷去 is 晋の師は之を聞き、為に
  // 罷め去る; 嘗謀事群臣莫能及罷朝而有喜色 朝を罷めて喜色有り;
  // 既罷歸國 既に罷めて国に帰る.
  //
  // KANJIDIC2 has まか.り- first — a *bound* form, hyphen and all, which is
  // 罷り出づ's 罷り and never stands alone — and や.める second. The two つか
  // the site prints (士民を罷らす, 楚は兵罷れ) are 疲 written with this
  // character, a third word, and are the two this entry gives away.
  罷: { conjClass: "shimo-nidan-ma", reading: "や", soleKun: true },

  // 反る / 反す ("to turn back, to return") and 空し ("empty, in vain") — the
  // two entries the paragraph at the head of this table says should not exist.
  // Both restate `derivedData`'s own leading sense and carry `soleKun` and
  // nothing else; see that paragraph for the reader's ruling and for why the
  // vote, not the dictionary, is what they stand in front of.
  //
  // kanbun.info prints 反(かえ) 20 times and 反(はん) 13 against our そ on all
  // 33, and 空(むな) 6 against our あ. The readings are stated in the modern
  // spelling the derived list and KANJIDIC2 both use, because that is what
  // `curatedStemKun` matches the kun against; the historical spelling is
  // applied downstream as it is for every other entry here.
  // 若く ("to be equal to") — 不若/未若, the negated comparison, where 若 is the
  // same word 如 is and takes the same 四段カ行 paradigm.
  //
  // **The derived list gets 如 right and 若 wrong**, and that asymmetry is the
  // whole fault: `derivedData` gives 如 `{yodan-ka, し}` — 如く, correct — and
  // 若 `{ku-keiyoushi, わか}`, which is the *modern* adjective 若い and no
  // reading of this character in kanbun at all. `overrides.json`'s ごと only
  // reaches a **positive** comparison, through `comparisonLexiconEntry`; a
  // negated one falls through to this table, so 未若貧而樂…者 came out
  // 者に**わかからず** — わか + ク活用 から + ず — where the received text reads
  // 者に若か**ざる**なり.
  //
  // kanbun.info's ruby is unanimous: over its prose 若 is glossed ごと 98, も 59
  // (若もし), **し 7**, したが 6, なんじ 6 — and わか not once. So this is a gap
  // in the derived data and an ordinary `RESIDUAL` fill, not an override of a
  // lemma the build script already resolves correctly.
  若: { conjClass: "yodan-ka", reading: "し" },

  反: { conjClass: "yodan-ra", reading: "かえ", soleKun: true },
  空: { conjClass: "shiku-keiyoushi", reading: "むな", soleKun: true },

  // 御す ("to drive, to control") — サ変. The site glosses 御 ぎょ **18** times
  // and ふせ once, never おん. 執古之道以御今之有 is 古の道を執りて、以て今の
  // 有を御し; 將能而君不御者勝 将の能にして君の御せざる者は勝つ;
  // 御其祿秩 其の禄秩を御し; 五曰御其服 五に曰く其の服を御す.
  //
  // **The class is サ変 and the derived entry's 四段サ行 is wrong**: the
  // received 御**せ**ざる is a 未然形 in せ, which only サ変 has (四段サ行 gives
  // 御さざる). So this is not a duplicate of `derivedData`'s ぎょ — it is the
  // correction of it, which is what this table is for.
  //
  // KANJIDIC2's three kun for 御 are おん-, お-, み-, **every one of them a
  // bound honorific prefix**, hyphen and all — お茶 and 御方's 御, which is not
  // a word a verb slot can hold. The app took the first and printed おん over a
  // character carrying a サ変 ending. The reading is written ぎよ at full size,
  // which is how this app spells a 拗音 (see `fullSizeKana`).
  御: { conjClass: "sa-hen", reading: "ぎよ" },

  // 挺く ("to spring back straight") — Wiktionary's only 挺す entry is the
  // unrelated on'yomi sense ていす ("to nominate oneself"), さ変; kanjidic's
  // sole attested kun'yomi for this sense is 抜く-shaped ぬ.く, a documented
  // best-effort guess (see the app's own reading-resolution notes), not a
  // confirmed traditional kundoku for this specific line.
  挺: { conjClass: "yodan-ka", reading: "ぬ" },

  // 博し ("broad, extensive") — no plain adjective entry at all in
  // Wiktionary; only na-adjective compounds (博学/博識/博雅) exist.
  博: { conjClass: "ku-keiyoushi", reading: "ひろ" },

  // 磨く ("to grind/polish", 金就礪則利's 礪) — has no entry at all (derived
  // or otherwise): kanjidic lists it under 磨/研, not this variant kanji, and
  // Wiktionary's own page for this word never lists 礪 among its spellings.
  // 四段カ行, the regular class for a plain -く verb like this.
  礪: { conjClass: "yodan-ka", reading: "みが" },

  // 無し ("there is not") — the derived entry for 無/无 is 為す's homophone
  // なす ("to do/make", a real but unrelated word also spelled 成す/為す),
  // the same cross-entry ambiguity as 成/為/成 above: 無 and 无 are both
  // attested kanji spellings of なす's kana headword too, and that entry
  // wins the extraction script's first-match race. ク活用, not a verb at
  // all — 無き人 (rentai), 無し (shuushi), matching real kanbun convention
  // (overrides.json's own contextPos:["VERB"] "なし" entry for this same
  // character is consequently never reached, since VERB_LEXICON is checked
  // first whenever pos is VERB — this residual entry is what actually fixes
  // it, not that override).
  無: { conjClass: "ku-keiyoushi", reading: "な" },
  无: { conjClass: "ku-keiyoushi", reading: "な" },

  // 戰/戦: three unrelated Japanese verbs share this spelling — たたかふ
  // "to fight" (四段ハ), をののく "to tremble" (四段カ) and そよぐ "to
  // rustle" (四段ガ) — and the build script, which takes the first entry
  // it can classify, lands on をののく. In kanbun the character is the
  // ordinary word for fighting or waging war; the trembling sense is a
  // different word that happens to be written the same way. The same
  // false-positive-on-another-sense case as 説/說 above, not mere
  // uncertainty. The class and reading match 闘/鬪, which the script
  // already resolves correctly for the same meaning.
  戰: { conjClass: "yodan-ha", reading: "たたか" },
  戦: { conjClass: "yodan-ha", reading: "たたか" },

  // 用ゐる ("to need, to require" — 俱言不須, "both said it was not needed"),
  // 上一段ワ行, the identical entry the build script derives for 用 itself.
  //
  // Here because of what 須's *other* use does to its dictionary entry. 須 is
  // a 再読文字, すべからく…べし, and KANJIDIC2's kun list for it leads with that
  // construction's own adverb: すべから.く, もち.いる, もと.める, in that order.
  // `pickKun` takes the first *dotted* reading for a VERB, so every 須 the
  // re-read rule declines — which, since `isRereadUse` now requires a governed
  // predicate, is every 須 with no verb under it — fell to すべから+く and read
  // 不須 as 須くず: the adverbial half of the very construction that had just
  // been ruled out, standing where a predicate belongs.
  //
  // The verb sense is the second dotted kun, and it is the one kanbun wants of
  // a bare 須. Stated here rather than by teaching the lookup to skip a
  // 再読文字's own adverb, because the reading and its class are what this
  // table is for and because the entry is checked ahead of KANJIDIC2 by both
  // panels at once — the re-read branch runs before either of them, so 須學 is
  // untouched and still reads すべからく學ぶべし.
  須: { conjClass: "kami-ichidan", okuriganaPrefix: "ゐ", reading: "もち" },

  // 出づ ("to come out, to emerge" — 哇有物出, "he retched, and there was
  // something that came out"), 下二段ダ行: 出で / 出で / 出づ / 出づる / 出づれ /
  // 出でよ.
  //
  // The same first-match-wins race 成/為 and 戰 above lose, not a gap: the build
  // script *does* classify 出, five times over (だす 四段サ行, でる twice, and
  // いづ/いず 下二段), and the sense it happens to reach first is the transitive
  // だす. In kanbun the character is the ordinary intransitive word for coming
  // out or emerging, and the transitive 出だす is the marked one. Wiktionary's
  // own 下二段ダ行 table for the word is the fourth entry in that list, so this
  // corrects which sense leads and states nothing the derived data does not
  // already hold.
  //
  // It is also what `nominalizedCandidates` in `reading/kanjidicLookup.ts`
  // nominalises, and the reason that function asks the lexicon before it asks
  // KANJIDIC2: 出's kun list leads with で.る, whose bare る `classicalConjClass`
  // can only read as 四段ラ行, so a 連体形 taken off the list would be 出る where
  // the word is 出づる.
  //
  // **And for a long time it reached almost nothing, because the vote answered
  // first.** 出's four dotted kun are two transitivity pairs (で.る/だ.す,
  // い.でる/い.だす), so every VERB 出 went to `pickByTransitivity`, which takes
  // the first candidate of the wanted kind — で.る for the 115 of the corpus's
  // 175 VERB tokens with no `comp:obj` — and reported `transitivitySelected`,
  // which stands this table down outright. The panels then inflected で- as
  // 四段ラ行 and wrote 出**り** for 出で and 出る for 出づる: this entry's own word,
  // spelled by the modern one's paradigm. The same shape 來's note above
  // records, and it is fixed the same way, by naming い.でる in
  // `SUPPLEMENTARY_KUN` (kanjidicLookup.ts) so that `pickKun` treats the
  // reading as settled and leaves the vote alone. That entry carries the
  // measurement and the one thing it costs — the transitive 出だす, which the
  // vote can no longer pick either.
  出: { conjClass: "shimo-nidan-da", reading: "い" },

  // 務む ("to apply oneself to, to make it one's business" — 君子務本, "the
  // gentleman applies himself to the root"), 下二段マ行: 務め / 務め / 務む /
  // 務むる / 務むれ / 務めよ.
  //
  // The same first-match-wins race 出 and 覺 above lose, and this one is lost to
  // a word that is not classical at all. The derived entry is 四段ラ行 with an
  // `okuriganaPrefix` of ま — つと**まる**, the modern intransitive "to be up to
  // the job" — and it printed 君子本を**務まり**, an intransitive verb governing
  // a direct object. KANJIDIC2 lists exactly one kun'yomi for the character,
  // つと.める, so nothing in the two dictionaries agrees with the sense the
  // script reached.
  //
  // **The resolver already had it right and could not be heard.** It answers
  // つと + む for this token — the correct 下二段 終止形 — but the transitivity
  // rule that would have marked the answer `beatsLexicon` never fires here:
  // `pickByTransitivity` needs two dotted kun'yomi to choose between and 務 has
  // one, so the resolver set no flag and `lexiconEntryFor` took the lexicon's
  // word. Corrected in the table rather than by weakening that precedence,
  // which is right for every other character.
  //
  // **Measured** over
  // `lzh_kyoto-sud-{train,dev,test}.relabeled_ext.udep_ruled.punct.rulemerged.adjfix.conllu`:
  // 務 stands as a VERB **46** times and governs a `comp:obj`/`comp:obl` in **23**
  // of them — 務民之義 · 其次務施報 · 務搏執 · 務畜菜 — every one the transitive
  // word. The intransitive つとまる occurs nowhere and cannot: it takes no object.
  務: { conjClass: "shimo-nidan-ma", reading: "つと" },

  // 覺ゆ ("to feel, to perceive" — 忽覺咽中暴癢, "suddenly felt a violent itching
  // in his throat"), ヤ行下二段: 覺え / 覺え / 覺ゆ / 覺ゆる / 覺ゆれ / 覺えよ.
  //
  // The same first-match-wins race 出 above loses, and it loses it to a word of
  // the opposite valency: the build script classifies the character exactly
  // once, as さます (四段サ行, 覚ます "to wake [something] up"), and that is what
  // led. In kanbun 覺 is the ordinary intransitive word for feeling or noticing
  // something in oneself, and 覺ます — waking another thing up — is the marked
  // one. 忽覺咽中暴癢 read 忽ち癢を覺ます, which says he woke the itch up.
  //
  // **Both senses survive this**, and the さます one has to: RESIDUAL is
  // prepended to a kanji's derived senses rather than put in their place (see
  // `LEXICON_SENSES`), so 覚ます stays in the list behind 覺ゆ, where a 覺 that
  // really does read さ still reaches it. This entry moves which sense leads; it
  // discards nothing.
  //
  // **It is also the sense a reader's own picked reading had no way to find.**
  // `attestedSenseByModernSpelling` at the foot of this file is what the
  // picked-reading path in `conjugationContext.ts` asks when the *shape* of an
  // okurigana settles no paradigm, and a bare える settles none — ア行, ヤ行 and
  // ワ行 下二段 have all collapsed onto it in modern spelling, the same wall 種's
  // entry above documents. A hand-picked `Reading=おぼ|Okurigana=える` therefore
  // had nothing to match: JMdict holds only the modern 一段 覚える, and the
  // derived さます shares neither the reading nor the modern spelling. So the
  // pick was frozen at its citation form 覺える where its coordination chain
  // wants the 連用形 覺え. `modernOkurigana` of ヤ行下二段 is える exactly, which
  // is what makes this entry reachable by that lookup rather than merely
  // present.
  覺: { conjClass: "shimo-nidan-ya", reading: "おぼ" },
  覚: { conjClass: "shimo-nidan-ya", reading: "おぼ" },

  // 暴かなり ("sudden, violent" — 忽覺咽中暴癢, "suddenly felt a violent itching
  // in his throat") — ナリ活用形容動詞: にはかなら / にはかに / にはかなり /
  // にはかなる / にはかなれ. The same shape as 仁 above: a reading KANJIDIC2 does
  // not carry at all (its 暴 is あば.く / あば.れる, the modern "expose" and
  // "rave"), supplied by `SUPPLEMENTARY_KUN` in `reading/kanjidicLookup.ts`,
  // with the paradigm here because a supplementary kun derives none by itself.
  // The reader has settled the word; the derived 四段カ行 あばく is a real but
  // different word, and it survives in `LEXICON_SENSES` behind this one.
  //
  // **What this entry reaches and what it does not.** Both panels consult the
  // lexicon only for a token `usesLexiconEntry` admits — VERB, ADJ, AUX, a
  // converb, and two named mis-taggings — so it inflects a 暴 tagged VERB (as
  // this reader's earlier trees had it) or the ADJ parser 0.3.2 gives the same
  // word, and not the ADV the current tree has. For
  // that one the 連用形 に comes from the resolver instead, which is right for
  // an adverb and is all an adverb ever needs; see `adverbialCopulaEnding` in
  // `reading/readingResolver.ts`. Making the ADV case go through the paradigm
  // as well is a change to `usesLexiconEntry`, not to this table.
  暴: { conjClass: "nari-keiyoudoushi", reading: "にはか" },

  // 縶る ("to tie up, to tether" — 縶手足, "binds his hands and feet"),
  // 四段ラ行: 縶ら / 縶り / 縶る / 縶る / 縶れ / 縶れ.
  //
  // Not uncertainty about a paradigm but a different *word*. KANJIDIC2 gives
  // 縶 one kun'yomi, つな.ぐ ("to tether"), and the build script has no
  // Japanese entry for the character at all — it is rare enough that
  // Wiktionary's Japanese data covers neither reading — so every 縶 fell to
  // the generic kanjidic path and read 縶ぐ. The reader wants しばる, which is
  // the ordinary word for binding a person, and 縶手足 is binding a person.
  // The same false-positive-on-another-sense shape as 說/戰 above.
  //
  // Its reading is also listed in `SUPPLEMENTARY_KUN` (kanjidicLookup.ts), and
  // it takes both tables for the reason 需's entry documents there: this one
  // holds the paradigm both panels conjugate through, that one makes しばル a
  // kun candidate so the furigana menu offers it beside kanjidic's own つなグ.
  縶: { conjClass: "yodan-ra", reading: "しば" },

  // 貯ふ ("to store up, to lay in" — 甕中貯水, "stores water in a jar"),
  // ハ行下二段: 貯へ / 貯へ / 貯ふ / 貯ふる / 貯ふれ / 貯へよ.
  //
  // **Which of two kanjidic kun'yomi leads, and what the ending then is.**
  // KANJIDIC2 gives 貯 た.める and たくわ.える, in that order, and `pickKun`
  // takes the first *dotted* reading for a VERB — so every 貯 read た+める,
  // whose める `classicalVerbEnding` converts to む: 貯む, 下二段マ行. The word
  // wanted here is the second one, 蓄ふ/貯ふ, and choosing between two real
  // readings of a character by sense is what this table is for.
  //
  // The reading is written **たくは**, historically, and that is not
  // decoration: it is the only place the historical spelling can come from.
  // The 歴史的仮名遣い index has nothing for 貯 but its on'yomi (ちょ -> ちよ),
  // no other character attests たくわ for `historicalByReading` to transfer
  // from, and `fullSizeKana` touches neither わ nor は — so the kanjidic path
  // can only ever print the modern たくわ. `lexiconFurigana` in KundokuView.ts
  // draws this string directly, which is the whole reason the lexicon's
  // readings are historical.
  //
  // ハ行下二段 rather than ワ行/ア行: the modern 貯える is a 下一段 verb whose
  // え descends from へ (ハ行転呼), the same shape 答ふ/與ふ/教ふ have, and
  // `classicalVerbEnding` refuses the whole あ row on its own for exactly the
  // reason this entry settles it by hand — a modern -eる could be ア行, ヤ行,
  // ワ行 or (through 転呼) ハ行, and the surface form cannot tell them apart.
  //
  // **It is also what a hand-picked たくわ+える reaches**, through
  // `attestedSenseByModernSpelling` at the foot of this file:
  // `modernOkurigana` of ハ行下二段 is える exactly, and the reading is
  // compared after the same modernisation, so the reader's own modern
  // spelling finds this classical sense. Without it a pick carrying the あ-row
  // ending had no paradigm at all — `chosenConjClass` abstains on it by
  // design — and 甕中貯水 printed the modern 貯える in the middle of a
  // classical text.
  貯: { conjClass: "shimo-nidan-ha", reading: "たくは" },

  // 瘦す ("to grow thin" — 體漸瘦, "his body gradually wasted"), 下二段サ行:
  // 瘦せ / 瘦せ / 瘦す / 瘦する / 瘦すれ / 瘦せよ.
  //
  // **The ending was being derived from a mis-divided modern kun, and the
  // class read off the wrong half of it.** KANJIDIC2 writes 痩 as や.せる and
  // its 旧字体 瘦 as やせ.る — the same word with the dot in a different place
  // — and nothing downstream can see that the boundary moved. From やせ.る
  // the reading is やせ and the okurigana a bare る, which
  // `classicalVerbEnding` leaves alone (a one-kana ending is already
  // classical) and `classicalConjClass` reads as 四段ラ行, the only paradigm a
  // lone る states. So 體漸瘦 came out 瘦り — the 連用形 of a verb 瘦る that
  // does not exist. The word is 下二段サ行 痩す, whose 連用形 is the bare せ.
  //
  // Both spellings, because the mis-division is only on one of them and the
  // answer is the same word either way: 痩's や.せる would derive 下一段 せる ->
  // 下二段サ行 unaided, and giving it the entry costs nothing while leaving the
  // two forms of one character to be read by two different routes would.
  瘦: { conjClass: "shimo-nidan-sa", reading: "や" },
  痩: { conjClass: "shimo-nidan-sa", reading: "や" },

  // 適く ("to go to, to proceed to"), 四段カ行 — asked for by name.
  //
  // The same first-match-wins race 出 and 覺 above lose, and this one the
  // build script loses to a real second sense rather than to a gap: it
  // classifies 適 twice, かなふ (四段ハ行, "to suit, to accord with") and
  // てきす (サ変), and かなふ leads. Both are words; neither is the one a
  // kanbun reader takes a bare 適 for, which is ゆく.
  //
  // **This table alone, unlike 需 and 縶, and the difference is measured.**
  // Those two pair a `RESIDUAL` class with a `SUPPLEMENTARY_KUN` reading so the
  // furigana menu can offer it; 適 cannot have that half. KANJIDIC2's only kun
  // for the character is かな.う, so a supplementary ゆ.く would be its *second*
  // dotted reading — and `pickKun` sends a VERB through `pickByTransitivity`
  // as soon as there is more than one. That check, asked about a 適 with no
  // object, answers かな.う and reports `transitivitySelected`, which sets
  // `beatsLexicon` and stands this entry down: the character went on reading
  // かなふ, by a longer route. So the menu offers テキ and かなフ and not ゆク,
  // and the reading on the page is not one of its own entries.
  //
  // かなふ is not discarded. RESIDUAL is prepended to a kanji's derived senses
  // (see `LEXICON_SENSES`), so 適ふ stays in the list behind this, where a
  // reader who picks かな still reaches it — which is exactly what the tree
  // this was measured against does on its own 適 (`Reading=かな|Okurigana=う`).
  適: { conjClass: "yodan-ka", reading: "ゆ" },

  // 熾んなり ("blazing, in full spate" — 饞火上熾, "the fire of his craving rose
  // and blazed") — ナリ活用形容動詞: 熾んなら / 熾んに / 熾んなり / 熾んなる /
  // 熾んなれ, with ん as `okuriganaPrefix` because the stem's last mora is
  // written beside the character and not over it (盛ん is the same word and the
  // same division).
  //
  // The same pairing 需 and 縶 above make, and for the same two reasons. This
  // table holds the paradigm: KANJIDIC2 divides the reading (once
  // `SUPPLEMENTARY_KUN` supplies 盛's own dot for it) but an ん settles no
  // class, so without a line here さかん conjugates nowhere. `SUPPLEMENTARY_KUN`
  // holds the division: KANJIDIC2 writes 熾's third kun as the undivided さかん,
  // which its dot convention makes a bare noun, and `pickKun` drops every bare
  // reading for a token tagged VERB.
  //
  // The build script's own answer for 熾 is おこ 四段サ行 (熾す, "to build a
  // fire"), which survives behind this in `LEXICON_SENSES` — a real word, and a
  // transitive one, where 饞火上熾 has the fire itself as its subject.
  熾: { conjClass: "nari-keiyoudoushi", okuriganaPrefix: "ん", reading: "さか" },

  // みる, 上一段 — the same verb 見る is, written with the other character.
  // Wiktionary files 視 as a soft-redirect to 見 and the build script takes
  // nothing from it, so `derivedData` has 視 as `null` while 見 comes back with
  // four senses, `kami-ichidan` み among them.
  //
  // KANJIDIC2 already gives the *reading* (み.る), which is why this went
  // unnoticed: with no class the character still printed 視る, and 上一段's
  // 終止形 and 連体形 are both みる, so the two forms anything asked for came out
  // right by coincidence. 解縛視之 is what breaks the coincidence — the clause
  // is a temporal protasis, `decideConjForm` answers `izen`, and with nothing
  // to conjugate with the panel wrote the resolver's citation okurigana and
  // then the particle after it: 之を視るば. 已然形 みれ is the first form of this
  // paradigm that is not the citation one.
  //
  // Reading supplied beside the class, as 適 and 曰 do, so the entry states one
  // sense rather than pairing a class with whatever reading arrives.
  視: { conjClass: "kami-ichidan", reading: "み" },

  // ── The 下二段 words a modern -eru spelling hides ───────────────────────────
  //
  // Six lemmas below, and one shape between them. KANJIDIC2 and Wiktionary both
  // write modern Japanese, where ア行・ヤ行・ワ行 and (through ハ行転呼) ハ行下二段
  // have all collapsed onto a single -eru: 伝える, 仕える, 構える, 添える, 与える,
  // 絶える. `classicalVerbEnding` refuses the whole あ row for exactly that reason
  // and says so at length, so a character whose kanbun word is 下二段 arrives here
  // with **no** classical ending at all — and what then speaks for it is whichever
  // *other* sense the two dictionaries happen to hold, which is a different word
  // every time. That is what each entry below states, one word at a time.
  //
  // `pairedARowKun` in `reading/kanjidicLookup.ts` reads the 行 off a sibling kun
  // of the same stem and so already writes 伝ふ 下二段ハ行 **into the furigana
  // menu**; it could never reach the page, because the page conjugates from this
  // table and this table was silent. The two now agree by construction: with a
  // sense here, `classicalVerbKun`'s first route (`attestedSenseByModernSpelling`)
  // answers before that rule is asked, and it answers the same ふ + 下二段ハ行 —
  // measured over all 12,356 characters of the shipped index, the rule stops
  // firing for exactly these six and the menu string for every one of them is
  // byte-identical to what the rule used to write. See that function's own doc,
  // which carries the count of what is left to it.

  // 傳ふ ("to hand down, to transmit" — 速於置郵而傳命, "faster than transmitting
  // an order by post-stage"), ハ行下二段: 傳へ / 傳へ / 傳ふ / 傳ふる / 傳ふれ /
  // 傳へよ.
  //
  // Two derived senses and neither is this word. The build script classifies 傳
  // twice — 四段ラ行 つた+は (傳はる, the modern intransitive 伝わる, "to be handed
  // down") and 四段ハ行 つた (傳ふ, 伝う, "to go along, to follow a line") — and the
  // first leads, so every 傳 in the corpus read 傳はる. 傳命 came out 命を傳はる, an
  // intransitive verb with a direct object. In kanbun 傳 is the ordinary transitive
  // word for handing something on, and its modern reflex is 伝える, which is
  // precisely the spelling Wiktionary has no 文語 table for.
  //
  // **Measured** over
  // `lzh_kyoto-sud-{train,dev,test}.relabeled_ext.udep_ruled.punct.rulemerged.adjfix.conllu`.
  // 傳 is **136** tokens — **VERB 115** (all of them `v,動詞,行為,伝達`), NOUN 20,
  // ADV 1 — and **76** of the VERB take a `comp:obj`, 3 a `comp:obl`. 伝 is **0**:
  // this treebank is written in 旧字体 throughout, and the shinjitai is here for
  // the reader's own text, not for the gold.
  //
  // Rendered both ways, **99** tokens change in **98** of the 68,893 sentences, and
  // every edit is the same word swapped for the other on the same slot: 傳はる ->
  // 傳ふ 69, 傳はり -> 傳へ 10, 傳はる -> 傳ふる 9, 傳はら -> 傳へ 7, and 4 more.
  // 不傳於賢，而傳於子 傳はらず -> 傳**へ**ず; 天下傳之久矣 傳はる -> 傳**ふ**.
  傳: { conjClass: "shimo-nidan-ha", reading: "つた" },
  伝: { conjClass: "shimo-nidan-ha", reading: "つた" },

  // 事ふ ("to serve" — 事父母幾諫, "in serving one's parents, remonstrate gently"),
  // ハ行下二段: 事へ / 事へ / 事ふ / 事ふる / 事ふれ / 事へよ. The same word 仕ふ is,
  // written with the character kanbun writes it with.
  //
  // A gap and not a false positive: Wiktionary has no verb entry for 事 at all
  // (`derivedData` holds `null`), so the reading came from KANJIDIC2, whose kun
  // list is こと / つか.う / つか.える. `pickKun` takes the first *dotted* reading
  // for a VERB, which is つか.う — 四段ハ行 — and 事君 read 君を事**ひ**て where
  // kundoku writes 君に事**へ**て. The two readings are the transitivity pair 仕ふ
  // and 使ふ have collapsed into one spelling; only the second is what a bare 事
  // means in Literary Chinese.
  //
  // **The NOUN is untouched and that is the whole reason this is safe.** 事 is
  // **1,715** gold tokens and **1,167** of them are the noun こと; only the **547**
  // VERB reach this table (`usesLexiconEntry`), every one of them carrying the
  // single xpos `v,動詞,行為,交流`, and **493** of those take a `comp:obj` —
  // 事父母 · 事君 · 以服事殷 · 非其君不事. There is no second verbal sense for an
  // entry keyed on the lemma to run over, which is the thing 鮮's entry below has
  // to give three tokens away to.
  //
  // Rendered both ways, **276** tokens change in **281** sentences, all of them
  // VERB and not one of them a noun: 事ふ -> 事ふる 73 (連体形), 事ふを -> 事ふるを 38,
  // 事は -> 事へ 35 (未然形), 事ふこと -> 事ふること 33, 事ひ -> 事へ 29 (連用形),
  // 事える -> 事ふる 13, 事へば -> 事ふれば 10 (已然形). 季路問事鬼神 鬼神を事ふ ->
  // 鬼神を事**ふる**; 事君，敬其事而後其食 事ひ -> 事**へ**.
  事: { conjClass: "shimo-nidan-ha", reading: "つか" },

  // 構ふ ("to build, to set up" — 構木爲巢, "built wood into a nest"), ハ行下二段:
  // 構へ / 構へ / 構ふ / 構ふる / 構ふれ / 構へよ.
  //
  // The same false-positive-on-another-sense shape 說 and 戰 above have. The build
  // script classifies 構 once, as 四段ハ行 かまふ — the modern 構う, "to mind, to
  // meddle with", a real word and an intransitive one — and that is what stood.
  // The transitive 構へる is the kanbun sense and is 下二段.
  //
  // **Measured**: 構 is **34** gold tokens — VERB **32**, of which **30** carry
  // `v,動詞,行為,設置` ("setting up") and 25 take a `comp:obj` — plus 2 PROPN (the
  // Song emperor 高宗's name 構). Rendered both ways, **21** tokens change in **18**
  // sentences: 構える -> 構へ 9, 構える -> 構ふ 5, 構えるを -> 構ふるを 4, and 3 more.
  // 構木爲巢 木を構える -> 木を構**へ**て巢を爲す; 又聞王敦與朝廷構隙 隙を構えるを ->
  // 隙を構**ふる**を.
  構: { conjClass: "shimo-nidan-ha", reading: "かま" },

  // 添ふ ("to add to, to append" — 添酒回燈重開宴, 白居易 琵琶行, "more wine was
  // poured, the lamps turned back, and the feast opened again"), ハ行下二段:
  // 添へ / 添へ / 添ふ / 添ふる / 添ふれ / 添へよ.
  //
  // The derived sense is 四段ハ行 そふ — 添う, "to be beside, to accompany", the
  // intransitive of the pair — and the kanbun 添 is the transitive one. Three gold
  // tokens and all three transitive (`v,動詞,行為,得失`, each with a `comp:obj`:
  // 添酒, 添薪, 添香), so the corpus does not so much confirm the sense as fail to
  // contradict it; the claim rests on the word, not on the count.
  //
  // Rendered both ways, **3** tokens in **3** sentences: 添える -> 添へ 2,
  // 添える -> 添ふ 1. 落葉添薪仰古槐 薪を添える -> 薪を添**へ**.
  添: { conjClass: "shimo-nidan-ha", reading: "そ" },

  // 與ふ ("to give" — 與之釜, "gave him a kettle"), ハ行下二段: 與へ / 與へ / 與ふ /
  // 與ふる / 與ふれ / 與へよ.
  //
  // **The reading was never wrong; the ending was frozen and the character was
  // gone.** Wiktionary has no entry for 與 or 与, so `derivedData` is `null`, and
  // what spoke was `overrides.json`'s curated `contextPos: ["VERB"]` entry, あた +
  // ふ. Every entry in that table is returned `spellOutInProse` and
  // `endingComplete` — that is what the table is for, function words written out
  // in kana — so a VERB 與 printed the bare kana **あたふ** in every syntactic
  // position and the kanji never reached the prose at all. 乞諸其鄰而與之 came out
  // その鄰に乞ひてこれを**あたふ**, where kundoku writes これに與**へ**. The
  // override still states the reading, and states the same あた this entry does;
  // what it cannot state is a paradigm.
  //
  // **Measured**: 與 is **2,183** gold tokens — ADP **1,477** (the comitative and
  // coordinating と), VERB **453**, PART **189** (sentence-final や), ADV **61**,
  // PROPN 2, NOUN 1 — and **298** of the VERB take a `comp:obj`. 与 is **0**, as
  // 伝 is. Rendered both ways, **374** VERB tokens change in **436** sentences:
  // あたふ -> 與ふ 171, あたふ -> 與へ 99, あたふ -> 與ふる 39, あたふを -> 與ふるを 21,
  // あたふと -> 與ふと 15, あたふこと -> 與ふること 13, あたふば -> 與ふれば 7.
  //
  // **The 61 ADV are not this word and are not left to it.** An adverbial 與 is the
  // comitative 與(とも)に — 可與言 is 與に言ふべし — and the parser tags it ADV with
  // `VerbForm=Conv`, which `isConverbUse` admits to `usesLexiconEntry`: this entry
  // reached all 61 and wrote 與**へ** on them, the right character conjugated as the
  // wrong word. They are claimed instead by an `overrides.json` entry of their own
  // (`contextPos: ["ADV"]`, とも + に, `beatsLexicon`), which is where a reading
  // chosen by the tag belongs and which stands this entry down for exactly those
  // tokens. See it for the measurement; nothing is narrowed here.
  與: { conjClass: "shimo-nidan-ha", reading: "あた" },
  与: { conjClass: "shimo-nidan-ha", reading: "あた" },

  // 絶ゆ ("to be cut off, to come to an end" — 火三月不絕, "the fire did not go out
  // for three months"), ヤ行下二段: 絶え / 絶え / 絶ゆ / 絶ゆる / 絶ゆれ / 絶えよ.
  //
  // **Two things were wrong and the second is the one that could not be seen.**
  // KANJIDIC2 gives 絶 three kun — た.える, た.やす, た.つ — and the build script
  // classifies the character once, as 四段サ行 た+や (絶やす, "to exterminate"), so
  // that led. Where the token had an object `pickByTransitivity` chose た.やす too,
  // and where it had none the answer was た.える, whose あ-row ending
  // `classicalVerbEnding` refuses outright: 火三月不絕 printed 絶**える**ず, a modern
  // 下一段 stem standing in front of a 文語 negation. So the intransitive had no
  // classical form at all, which is what this entry supplies.
  //
  // **Measured**: 絶 (lemma; the treebank writes the form 絕 174 times and 絶 45)
  // is **219** gold tokens — VERB **217**, ADV 2 — and **119** of them take a
  // `comp:obj` against **98** with none. Rendered both ways, **166** tokens change
  // in **164** sentences: 絕やす -> 絕ゆ 66, 絕やし -> 絕え 26, 絕やさ -> 絕え 20,
  // 絕やす -> 絕ゆる 13, 絕やすを -> 絕ゆるを 12, 絶える -> 絶ゆ 8, 絕やせば -> 絕ゆれば 7.
  // 親未絕而列於庶人 いまだ絕やさず -> いまだ絕**え**ず; 骨肉之親無絕也 -> 絕**ゆる**無し.
  //
  // **It costs the 119 transitives, and nothing here can save them.** Classical
  // Japanese separates 絶ゆ (下二段ヤ行, intransitive) from 絶つ (四段タ行, transitive),
  // and this table is keyed on the lemma alone, so the distinction cannot be drawn
  // from here at all — 在陳絕糧 will read 糧を絕**ゆ** where it wants 糧を絕**つ**.
  // The evidence that would draw it is in the tree and not in the dictionary (an
  // object, or none), which is `pickByTransitivity`'s question and not this one's;
  // KANJIDIC2's own た.つ is the third of three dotted kun and that function ranks
  // by JMdict transitivity rather than by list order, so it answers た.やす — a real
  // word, and the causative-ish one — where 絶つ is wanted. The reader has ruled
  // 絶ゆ, which is the reading of the character standing on its own, and the 119
  // are the price stated rather than hidden. Correcting them is a transitivity
  // question for `reading/kanjidicLookup.ts`, not a second entry here.
  絶: { conjClass: "shimo-nidan-ya", reading: "た" },
  絕: { conjClass: "shimo-nidan-ya", reading: "た" },

  // 遣はす ("to send a man on a mission, to dispatch"), 四段サ行 つか + `okurigana
  // Prefix` は: 遣はさ / 遣はし / 遣はす / 遣はす / 遣はせ / 遣はせ. 乃遣沛公 is 沛公を
  // 遣はす, 武帝遣使 is 武帝使ひを遣はす, 遣張騫 is 張騫を遣はす.
  //
  // **The same cross of two words 絶's entry above records, and it surfaced the
  // same way.** The build script's one derived sense for 遣 is `yodan-sa` + や —
  // 遣る's stem や on 遣はす's サ行四段 paradigm — which spells 遣**す**, やす, a
  // word in neither language. It printed nowhere while the causative gate did
  // not exist (`AUXILIARY_LEMMAS` holds 遣 keyed on the lemma, so every token
  // rendered しむ); `readsAsCausative` stands the auxiliary down where the
  // character governs no caused predicate, which is **107** of 遣's 332 gold
  // tokens, and that is what put やす on the page.
  //
  // **遣はす and not 遣る, and the corpus is what chooses.** Both are real
  // readings of the character and KANJIDIC2 lists both (つか.わす and や.る), so
  // the question is which word this text is using. 遣 is `v,動詞,行為,使役` in
  // **all 332** occurrences — the treebank files it with 使 and 令 and 敎, as a
  // verb of dispatching, and it has no second class here to divide. **310** of
  // its 330 VERB tokens take a `comp:obj`, and those objects are people:
  // **240** of the 320 are `n,名詞,人,*` (役割 113 — 使 itself 57 of them, 將 21,
  // 兵 21 — 姓氏 70, 名 24, 人 23, 関係 10) and 17 more are personal pronouns,
  // against **3** portable objects in the whole corpus. That is 遣はす's argument
  // structure exactly: 使ひを遣はす, 將を遣はす, 沛公を遣はす. 遣る is the general
  // "send off, let go, give" — 心を遣る — and dispatching a named man to a court
  // on the king's business is not what it says. 遣はす is also the received
  // kundoku of the character, and it shares its stem つか with 使ふ, which is the
  // sense both characters carry.
  //
  // **The reading is つか and the は is okurigana**, not つかは over the
  // character, for the reason 來's entry two dozen lines above gives: this app's
  // kanbun convention shows the は visibly beside the kanji (遣はす, as 来たる),
  // and the stem it leaves over the character is the same つか the 使 of
  // 使ひ/使ふ takes. Written historically, は rather than わ, because
  // `historical-kana-index.json` holds 遣 as つかい -> つかひ and nothing for
  // つかわ, so a modern わ would have reached the page unconverted.
  //
  // **Measured** over the same gold, against a baseline re-rendered immediately
  // before: **101** tokens change their prose — 遣はす 89, 遣はさ 4, 遣はすを 3,
  // 遣はし 2, 遣はして 2 (the two ADV, 遣歸 as 遣はして歸る), 遣はしに 1 — in 100
  // sentences. 武帝遣使 goes from 武帝は**つかふ**を**遣す** to 武帝は使ひを遣はす,
  // both halves of it (the 使 is `kanjidicLookup.ts`'s supplementary kun).
  //
  // **The other 230 tokens print exactly what they printed**, and neither group
  // is a page this entry reaches. **225** are the ones `readsAsCausative` keeps
  // as しむ, whose cell carries no furigana at all — `KundokuView.ts` passes
  // `undefined` for a 使役 auxiliary and puts the whole word in the okurigana
  // slot — and **5** are members of a fused span (遣車, the hearse of 遣車一乘,
  // and 在遣中), whose ruby `compoundFurigana` writes for the whole word. One
  // more span is the single 遣す left standing: 分遣 is ぶんけん to the pair rule,
  // which sets `beatsLexicon` and stands this entry down, and 分遣す is the right
  // word for it.
  遣: { conjClass: "yodan-sa", okuriganaPrefix: "は", reading: "つか" },

  // 調ふ ("to put in order, to muster, to levy, to season"), 下二段ハ行 ととの:
  // 調へ / 調へ / 調ふ / 調ふる / 調ふれ / 調へよ. 轉漕調兵 is 兵を調ふ, 和調五味而
  // 進之 is 五味を調へてこれを進む, 三公調陰陽 is 三公陰陽を調ふ.
  //
  // **The note below said the corpus does not choose. It does, and the axis it
  // was looked for on is the wrong one.** 調 is 48 gold tokens — VERB **29**,
  // NOUN 16, PROPN 3 — and the 29 divide **13** with a `comp:obj` against 16
  // without, not 13 against 15. Transitivity was the obvious place to look and
  // it separates nothing here, because *both* words are transitive: JMdict has
  // 調べる transitive and 調える transitive, so `pickByTransitivity`, asked about
  // a 調 that governs an object, answers with whichever stands first in
  // KANJIDIC2's list — しら.べる — and reports the syntax as having chosen it.
  // The note's own two worked examples are the proof, and it did not notice:
  // 調竽笙竾簧 (しらぶ) and 轉漕調兵 (ととのふ) both have an object.
  //
  // **What does separate them is what is being 調'd, and on that the corpus is
  // nearly unanimous.** Of the 29 VERB tokens, **9** print the bare character
  // because they are half of a Sino-Japanese compound (調護 ×2, 調度 ×2, 調停,
  // 調戲, 調援, 調益, 調角) and **1** is the courtier 李調, whom the treebank tags
  // PROPN in his other three occurrences and VERB in 調也君之褻臣也 — a mis-tag,
  // named rather than worked around. That leaves **19** verbal uses, and **18**
  // of them are ととのふ in one of its senses: mustering men (轉漕調兵, 調校尉以來,
  // 乞調諸道兵, 金人遂調兀朮, 內調工役), bringing into balance (三公調陰陽, 是以陰陽調,
  // 調輕重, 摯咎繇而能調), seasoning (和調五味而進之, 調之以醯醢, 調以滑甘, 夕調乎酸鹹,
  // 夕調乎鼎鼐), making ready (方將調鈆膠絲), being in tune (琴瑟不調), and the two
  // the parse leaves standing out of a compound (才調, 變調). The **one**
  // exception is 調竽、笙、竾、簧 — tuning the pipes, which is しらぶ — and it is
  // the price of this entry, stated rather than hidden. しらぶ stays in
  // `LEXICON_SENSES` behind this and in the furigana menu, where the reader can
  // take it back on that one line.
  //
  // **It takes both tables, for the reason 需's and 縶's entries give.** A
  // `RESIDUAL` entry alone changes nothing: `pickByTransitivity` reports
  // `transitivitySelected` on every one of the 13, which sets `beatsLexicon` and
  // stands this entry down — the exact shape 適's paragraph below records. What
  // stops the vote is `SUPPLEMENTARY_KUN`'s ととの.ふ (kanjidicLookup.ts): a
  // hand-supplied reading is not put to a vote, and the reading it supplies —
  // the classical 終止形 of the transitive word — is one the index does not
  // carry, holding only the modern 下一段 ととの.える. The class has to be here
  // even so, because ふ alone reads as 四段ハ行 to `classicalConjClass` and this
  // verb's transitive paradigm is 下二段.
  //
  // **下二段 and not 四段**, which is the same word's intransitive twin (琴瑟調はず,
  // "the qin and se are not in tune"). The two differ only outside the 終止形, so
  // the choice costs less than it looks: of the 19 verbal tokens exactly **4**
  // stand in a form that tells the paradigms apart, and 3 of those 4 are
  // transitive — 和調五味 (調へて, not 調ひて), 調鈆 (調へ), 調以滑甘 (調ふること).
  // The fourth is 琴瑟不調, which wants 調はざる and gets 調へざる. The transitive
  // is what this character mostly is here, so the transitive paradigm leads.
  //
  // **Measured** over `lzh_kyoto-sud-{train,dev,test}.relabeled_ext.udep_ruled.punct.rulemerged.adjfix.conllu`,
  // against a baseline re-rendered immediately before: **14** of the 68,893
  // sentences change and every one of them contains 調 — 11 tokens off しらぶ
  // (調ぶ -> 調ふ 9, 調べ -> 調へ 2), 調ふこと -> 調ふること, 調ふを -> 調ふるを, and
  // 琴瑟調はざる -> 調へざる.
  //
  // **A general repair was tried first and rejected on the measurement.**
  // `pickByTransitivity`'s real flaw is that it answers with the first candidate
  // of the wanted transitivity even when two *different words* share it — for
  // 調 the transitive set is しら.べる and ととの.える, and an object says nothing
  // about which. Making the vote decline where the matching candidates disagree
  // about their stem is the principled statement of that, and it is a disaster:
  // the fallback is KANJIDIC2's own first dotted kun, and **4,228** sentences
  // change, 4,214 of them nothing to do with 調 and nearly all for the worse —
  // 行ふ -> 行く, 生くる -> 生かす, 違ふ -> 違し, 治む -> 治る, 恐る -> 恐し. The
  // vote's list-order answer is usually right; it is wrong for this character,
  // and one character is what the supplement is for.
  調: { conjClass: "shimo-nidan-ha", reading: "ととの" },

  // 敎/教 — 教ふ, 下二段ハ行 をし ("to teach"). **An entry here was refused once,
  // and the refusal was right at the time**: 敎 stands in `AUXILIARY_LEMMAS` and
  // `CAUSATIVE_LEMMAS` keyed on the lemma alone, so all **202** of its gold VERB
  // tokens rendered as the 使役 auxiliary しむ with the kanji dropped, and an
  // entry that prints nowhere is worse than no entry — it would still have put
  // をし over the character in the 訓読文, which is the two panels disagreeing
  // about one word. What was needed first was the gate, and it is now written:
  // `readsAsCausative` (conjugationContext.ts) stands the auxiliary down where
  // the character governs no caused predicate, which is **137** of the 202.
  // 教不倦 is 教へて倦まず, 其所教 is 其の教ふる所, 不教而殺 is 教へずして殺す,
  // 后稷教民稼穡 is 民に稼穡を教ふ. This is the word those 137 are.
  //
  // **Wiktionary's own data cannot supply it, and supplies a near miss instead.**
  // The build script derives 教 (U+6559) as `yodan-ra` をそ + `okuriganaPrefix`
  // は — 教はる, "to *be* taught", the passive-ish 四段 sibling — and derives
  // nothing at all for 敎 (U+654E), which is the spelling the treebank
  // lemmatizes every one of the 338 occurrences to. So the transitive 教ふ has
  // no derived sense under either spelling, and the one sense there is belongs
  // to a different word. Both are listed here, for the reason `CAUSATIVE_LEMMAS`
  // gives at length — nothing folds a lemma to a single spelling before these
  // tables are keyed by it — and RESIDUAL going in front rather than replacing
  // leaves 教はる behind 教ふ rather than discarding it.
  //
  // **をし and not おし**, written historically here rather than left to the
  // render-time correction, because that correction is keyed by `token.text`
  // and the character is written both ways: `historical-kana-index.json` holds
  // 教 (おし -> をし) and holds no 敎 at all, so a modern おし would come out
  // をし over 教 and おし over 敎 — one word spelled two ways on one page. The
  // same reason 暴 above is entered as にはか.
  //
  // Without the entry the gate has nothing to fall back on and the failure is
  // the one 絶 above records: KANJIDIC2's kun is おし.**える**, a modern 下一段
  // ending `classicalVerbEnding` will not convert, so 教不倦 printed
  // 教**える**ず — a modern stem standing in front of a 文語 negation. Rendered
  // with the gate and without this entry, **103** gold sentences came out that
  // way; with it, none does.
  //
  // **Measured**, gate and entry together, over the same gold: **229** of the
  // 338 敎 tokens change. The 202 VERB divide **65** causing / **137** not, and
  // **114** of the 137 move — 教ふ 43, 教ふる 37, 教へ 19, 教ふと 4, and the
  // 敎-spelled equivalents 8, 2, 1 — the remaining 23 being members of a fused
  // span (敎化, 教育) that take no ending of their own and never printed しむ.
  // The **134** NOUN, which nothing on the auxiliary path ever gated on POS,
  // divide 0 causing / 134, and **114** of them stop printing しむ and simply
  // keep their character with no ending at all: 教 101, 敎 12, and one 教なり
  // where a 也 closes the clause — 校者、教也 is 校なる者は教なり.
  敎: { conjClass: "shimo-nidan-ha", reading: "をし" },
  教: { conjClass: "shimo-nidan-ha", reading: "をし" },

  // **Seven, and four others were looked at and refused.** `pairedARowKun` names
  // sixteen characters whose menu carries a modern -eru beside a classical sibling;
  // the nine not above are here so the next reader does not rediscover them (敎
  // was the tenth and has since been entered, immediately above, and 調 the
  // eleventh):
  //
  //  - **敎/教** was refused here and is now entered above, the refusal having
  //    been about the causative gate and not about the word. See that entry.
  //  - **從/从** already lead with the right sense. The kanbun 從 is 四段ハ行
  //    したがふ ("to follow" — 從我者 is われに從ふ者), which is exactly the derived
  //    first sense; the 下二段 したがへ ("to lead in one's train") is the marked one
  //    and survives behind it in `LEXICON_SENSES`. 从 reaches neither, having no
  //    entry of its own — see `shinjitai-index.json`, which cannot supply the
  //    variant either (kaikki's `pos: "character"` record for 从 carries no
  //    `forms` and no `alt_of` at all).
  //  - **震** is 震ふ 四段ハ行 and already reads so: KANJIDIC2's ふる.う leads and
  //    `hagyouShuushi` gives it ふ. The 下二段 震へ is the modern 震える, a different
  //    word from the 震 of 地震 and 名震關西. 36 gold VERB tokens, 8 with an object.
  //  - **調** was refused here on the ground that the corpus does not choose. It
  //    does, and the note that said otherwise had the axis wrong as well; it is
  //    now entered above. See that entry.
  //  - **浚** is 浚ふ 四段ハ行 and reads so already; 井を浚ふ is the ordinary
  //    collocation for dredging and the 下二段 さらへ is not more secure than it.
  //    3 gold VERB tokens, against 48 PROPN (the Song general 張浚).
  //  - **揃** has **0** gold tokens and is not そろふ in Literary Chinese at all —
  //    the character means "to clip, to shear" there (KANJIDIC2's own fourth kun,
  //    き.る). そろえる is a Japanese-only reading of it.
  //
  // 叓/亊 (variants of 事) and 构 (of 構) and 沗 keep their menu conversion from
  // `pairedARowKun` and get no entry here, for the reason that rule's doc gives:
  // this table is keyed on the lemma, and the treebank lemmatises none of them.

  // 異なり ("to be different from") — ナリ活用形容動詞, and the next of the
  // virtue-noun shape 仁's own note says each addition will be (仁, 賢, 大, 暴,
  // 熾 are the others). 其諸異乎人之求之與 is 人の之を求むるに**異なる**か, which
  // kanbun.info prints; the app wrote 異**る**, and the reader reported it as
  // 「異 is glossed as ことる」.
  //
  // **ことる is not a word in any paradigm**, and that is why the complaint
  // arrived as one about the *menu*: `candidateReadings` never offered it, and
  // could not — 異's only kun'yomi is こと.なる, which the menu offers whole as
  // こと + ナル. ことる was not a candidate at all but a form the conjugation
  // produced after the fact, out of a class attached to a stem that never grew
  // it. A page showing what the menu cannot offer is exactly that symptom.
  //
  // **Where the wrong class came from: it is derived, not stated.** Nothing in
  // `reading/classicalEnding.ts` answers for なる (な is a row in neither
  // `KAMI_NIDAN_SHUUSHI` nor `SHIMO_NIDAN_SHUUSHI`, so `classicalConjClass`
  // returns undefined), and `attestedClassicalParadigm` answers nothing either.
  // The class came from `derivedData` — `verb-lexicon-index.json` held 異 as
  // `{ conjClass: "yodan-ra", reading: "こと" }` — by way of the build script's
  // *godan fallback* (`GODAN_ROW_OF_FINAL_KANA`), which reads a modern godan
  // verb's ending as 四段 of the same row and takes the stem to be everything in
  // front of it. Modern 異なる really is a 五段ラ行 verb, so the fallback fired
  // and left こと + る. `scripts/build-verb-lexicon.mjs` already knows this word
  // defeats it: `EXTRA_SUFFIX_OF`'s own doc names 異なる's
  // なら/に/なり/なる/なれ/なれ as one of the four bungo blocks that match no
  // paradigm it can emit, because 形容動詞 reach that index through `kuOrShiku`
  // from *adjective* entries and Wiktionary files this one as a verb. A stated
  // entry is what that note asks for, and is not a word "the script can already
  // resolve" in the sense this table's own header forbids hand-adding.
  //
  // **Only 異, and the shape was measured before it was narrowed to one.** An
  // okurigana of なる derived as a 四段ラ行 ending is the general form of the
  // fault, so every character KANJIDIC2 writes 〜.なる for was enumerated over
  // the shipped `public/data/kanjidic-index.json`: **16**, and no character is
  // written 〜.なり at all. Fifteen of the sixteen are 重なる (かさ.なる, with
  // 畳/疊/疉/疂/佹/叠/紈) or 連なる (つら.なる, with 聯/緜/聨/峮/嶧/巋) — both
  // genuine 四段ラ行 verbs, not this fault — and rendered one by one none of
  // them loses its な: 重なる, 連なる, 聯なる, 緜なる, 佹なる, 紈なる, 峮なる,
  // 嶧なる, 巋なる, with the 畳/疊/疉/疂/叠 family reading たたむ off its own
  // first kun instead. 重 and 連 are the two the build script classified from a
  // real bungo table, and their derived senses carry `okuriganaPrefix: "な"` —
  // which is precisely what the godan fallback cannot supply and 異 therefore
  // went without. So the measurement licenses one entry and no rule.
  //
  // **Measured** over `lzh_kyoto-sud-{train,dev,test}.relabeled_ext.udep_ruled.
  // punct.sjmerged.conllu`. 異 is **257** tokens: **VERB 223** — `mod` 95,
  // `parataxis` 38, `root` 31, `comp:obj` 30, `conj:coord` 16 and 13 more on
  // `flat@vv`/`comp:pred`/`subj`/`comp:aux` — **PROPN 19**, **ADV 11** and
  // **NOUN 4**. Only the 223 reach this table (`usesLexiconEntry`), and every
  // one of them carries the single xpos `v,動詞,描写,形質`: there is no second
  // adjective sense in the corpus for a lemma-keyed entry to run over. The
  // `adjfix` variant of the same treebank tags those same 223 **ADJ**, which is
  // what the shipped 0.3.x parser and `rongo-gakuji.conllu` write.
  //
  // The derived 四段ラ行 sense is not discarded — `LEXICON_SENSES` keeps it
  // behind this one, where a reader who really wants the modern verb can still
  // reach it, exactly as 熾's おこ sits behind さか.
  //
  // **The menu needs a second statement, and it is in `classicalEnding.ts`.**
  // This entry is read by the two panels and by nothing else; the furigana menu
  // offers KANJIDIC2's kun'yomi as written, which is the modern こと + ナル, and
  // `attestedSenseByModernSpelling` cannot bridge the two because
  // `modernOkurigana` is undefined for ナリ活用 by construction. `LEXICAL_KUN`
  // there now holds ことなる, so the menu offers こと + ナリ carrying this class
  // and a picked 異 inflects by the paradigm the page inflects by. That row is
  // also what makes `derivedConjClass` answer for 異 — the two senses here
  // share the reading こと, so `soleAttestedClass`, which is the last thing it
  // would otherwise ask, abstains for exactly this character.
  //
  // **It measured 2 edits worse on the gold tier when it went in, and the
  // fault was not here.** All of the regression was one slot: the ナリ
  // 連用中止形 異**に** written where kanbun.info closes the sentence on the
  // 終止形 異**なり** — 是に異なり (論語 13.18, 19.03), 吾が聞く所に異なり. The
  // form was right for what the tree said and the tree was being read across a
  // mark: the treebank punctuates 異於是**：**父爲子隱, and `CLAUSE_CLOSING_MARKS`
  // (conjugationContext.ts) did not hold the ：, so `predicateCoordinationChain`
  // walked on into the next sentence and `isNonFinalCoordinand` demoted a
  // predicate that in fact closes its own. That set now holds the ：, on the
  // reader's ruling and on its own measurement, and with it this entry reads
  // **4 edits better on the gold tier and 1 on the parser** — measured by
  // rendering the corpus with and without the entry, both with the mark in the
  // set, in one process. 我則異於是**，**無可無不可 (論語 18.08) is the one that
  // still costs an edit; the treebank writes a ， where kanbun.info ends the
  // sentence, and nothing in this app can tell that ， from an enumerating one.
  異: { conjClass: "nari-keiyoudoushi", reading: "こと" },

  // **在り is ラ変, and the 四段ラ行 the index holds for it is the godan
  // fallback again** — 異 above is the same fault under a different ending, and
  // this is the second character caught by it. 國破山河在 closes on 山河**在り**
  // in the received reading of 春望, and the app wrote 山河**在る**.
  //
  // **One cell separates the two paradigms, and it is the one a sentence ends
  // on.** ラ変 is ら/り/**り**/る/れ/れ and 四段ラ行 ら/り/**る**/る/れ/れ: they
  // differ in the 終止形 alone, so every 在 standing inside its clause was
  // already right and only a 在 closing one was wrong — which is why a character
  // this common could carry a wrong class for as long as it did. The ラ変型 rule
  // hangs off that same cell: `RA_HEN_TYPE_CLASSES` holds `ra-hen` and
  // `shuushiConnectiveForm` gives a 終止形接続 助動詞 the **連体形** of anything
  // in it, so 可在 comes out 在る可し rather than 在可し by the class alone.
  //
  // **Where the wrong class came from.** KANJIDIC2 writes 在 as あ.る, modern
  // 在る is a 五段ラ行 verb, and `GODAN_ROW_OF_FINAL_KANA`
  // (`scripts/build-verb-lexicon.mjs`) reads that ending as 四段 of the same row
  // with everything in front of it for a stem — あ + る. Wiktionary files no
  // classical block for the character that would have overruled it, exactly as
  // 異's own note describes for なる.
  //
  // **有 and 居 are the neighbours, and both are already right**: `derivedData`
  // holds 有 as `{ ra-hen, あ }` and 居 as `{ ra-hen, お }`, classified off real
  // bungo tables, and 侍 as `{ ra-hen, はべ }` behind its three ハ行四段 senses.
  // The classical ラ変 is a closed set of four — あり・をり・はべり・いまそかり,
  // named in `classicalConjugation.ts`'s own row — and 在 is a character the
  // first of them is written with. So this entry states for 在 what the index
  // already says of the rest of the class.
  //
  // **The reading was never in question and neither derived sense is lost.**
  // The site's ruby on 在 is あ **210**, いま 8, あきら 1, ざい 1; the 四段ラ行
  // sense stays behind this one in `LEXICON_SENSES` and 在す (四段サ行 いま) —
  // the いま those 8 are — behind that, where a reader can still reach either.
  //
  // **Measured** over kanbun.info's 3,419 passages, against the tree rendered
  // immediately before in the same process. 在 is **220** tokens there (gold 44,
  // parser 176) and every one of them is tagged VERB — `root` 58, `comp:obj` 54,
  // `parataxis` 48, `conj:coord` 35, `mod` 14 and 11 more — so there is no
  // second sense for a lemma-keyed entry to run over. **17 edits better on the
  // gold tier and 33 better on the parser**, 60 passages moving, 52 the right
  // way against 8 the wrong way, and every one of the gold's 16 the right way:
  // 論語 2.18 41 → 40 (祿其の中に在り), 5.1 28 → 27, 6.9 8 → 7 (陋巷に在り), 7.15
  // 13 → 12, 9.10 61 → 60, 12.2 51 → 49 (邦に在り怨しき無し, twice in one passage).
  //
  // **The 8 are one shape, and it is a 連体形 this app does not know it owes.**
  // All are on the parser tier and all read 在**り** where the received text has
  // 在**る** — 日者月在箕壁翼軫也 (孫子 12) is 箕・壁・翼・軫に在る**なり**, 仁之所在
  // (六韜 1) is 仁の在る**所**, 其失安在 (六韜 10) is 其の失安くにか在る, a 係り結び
  // on か. Each is an attributive context `decideConjForm` does not recognise,
  // and 四段ラ行 was **accidentally right** in all of them: that paradigm spells
  // its 終止形 and its 連体形 alike as る, so a wrong form under a wrong class
  // printed the right kana. The regression is the app writing a 終止形 where a
  // 連体形 belongs, which is a defect of its own and not this entry's to carry;
  // stated here so that whoever fixes it can find the eight passages that pay
  // for it. The reading ratchet does not move at all: 在 is outside its
  // disagreement set before and after, the character having read あ all along.
  在: { conjClass: "ra-hen", reading: "あ" },

  // **寢(い)ぬ, 寐(い)ぬ — ナ行下二段**, one word under two characters and the
  // same shape as 出 above. 寢's leading derived sense is 四段ラ行 ね (寢りて) and
  // its ナ行下二段 sense sits third; 寐 has no derived sense at all, and its
  // only kun is ね.る. The received text writes 寝ぬる, 寝ぬ, 寝ねず, 寝ねて, 寝ね
  // and 寐ねて, 寐ぬるは — 未然/連用 ね, 終止 ぬ, 連体 ぬる, 已然 ぬれ, 命令 ねよ,
  // with the character covering い. 新字体 寝 is entered beside 寢 exactly as 説
  // is entered beside 說 above. `SUPPLEMENTARY_KUN` carries the reading for the
  // reason 出's does, and has to state い.ぬ for 寐, which KANJIDIC2 does not
  // list it for. **2 edits better on the gold tier and 5 on the parser**, 7
  // passages moving.
  //
  // **經 was asked with them and is not here.** It is the third member of the
  // family — ハ行下二段 經(ふ), whose 未然/連用 is へ and whose 終止 is ふ — and
  // it is the one this file cannot state, because the word has no stem: the
  // division falls *inside* the inflection (經(へ)て, 經(ふ)る), which is what
  // `INFLECTING_READINGS` in `classicalConjugation.ts` exists for and what that
  // table can hold for ア行下二段 alone. Entered here as `shimo-nidan-ha` with a
  // reading of へ it writes the ending twice — 經へふる — and measured as
  // 經 + へ.る in `SUPPLEMENTARY_KUN` it reads **level on the gold tier and 2
  // worse on the parser**. The character is 9 NOUN tokens against 9 VERB over
  // the corpus and the received text reads most of them as the noun 経, so
  // there is little at stake either way; what it would need is a *per-lemma*
  // inflecting reading, which is a table this project does not have.
  寢: { conjClass: "shimo-nidan-na", reading: "い" },
  寝: { conjClass: "shimo-nidan-na", reading: "い" },
  寐: { conjClass: "shimo-nidan-na", reading: "い" },

  // **復む — マ行四段**, the verb of 言可復也 ("a word that can be made good"),
  // which kanbun.info reads 言復む可きなり. KANJIDIC2 gives 復 one kun'yomi, the
  // undotted また, so a VERB-tagged 復 resolved to a bare adverb with no
  // okurigana at all and the two panels printed 言復た可きなり — the adverb
  // standing where the received text has the verb. The same fault 主 and 友
  // above are entered for, and named one word at a time for the same measured
  // reason: the general rule ("a VERB whose every KANJIDIC2 kun is undotted")
  // reads 21 gold and 442 parser edits worse.
  //
  // The adverb is untouched — `usesLexiconEntry` admits only a VERB, and 復 is
  // ADV in 42 of its 64 tokens over the kanbun.info corpus, every one of which
  // goes on reading また. **1 edit better on the gold tier and 1 worse on the
  // parser.** The one regression is 水上軍開入之、復疾戰, where the received text
  // reads 復た and the parser has tagged that 復 VERB; that is a mis-tag and not
  // this entry's to answer for.
  復: { conjClass: "yodan-ma", reading: "ふ" },

  // **宗ぶ — バ行四段, たふとぶ**, the verb of 亦可宗也, which kanbun.info reads
  // 亦た宗ぶ可きなり. 宗's only kun'yomi is the undotted むね, so the character
  // came back a bare noun exactly as 復 did and the app wrote 亦た宗なり可き — a
  // noun and a copula where the received text has a verb. The word is 尊ぶ /
  // 貴ぶ, 四段バ行, whose 終止形 ぶ is what the 可 attaches to; its 歴史的仮名遣い
  // stem is たふと (modern たっとぶ / とうとぶ), written here for the reason 貯's
  // たくは is. The noun is untouched: 68 of the corpus's 69 宗 are NOUN, and the
  // single VERB token is the one this reaches. **1 edit better on the gold
  // tier.**
  宗: { conjClass: "yodan-ba", reading: "たふと" },

  // **罔し and 靡し — the ク活用 な that 莫 and 毋 already hold**, and here now
  // because the reader has ruled that alignment with the received text
  // decides. `POSTPOSE_PREDICATE_NEGATION_LEMMAS` (depClassification.ts) moves
  // both to where kundoku reads them, and with no entry each printed as a bare
  // character with nothing after it.
  //
  // Both were left out on linguistic grounds, and both were then measured
  // against those grounds. **罔 has a second kanbun reading** a lemma-keyed
  // entry cannot separate — 學而不思則罔 is くらし and not なし — and the received
  // text writes it 罔**く** all the same, which is the 連用形 of a ク活用 whatever
  // the stem under the character is, so the entry aligns on the very passage
  // that was the objection: **1 edit better on the gold tier**, on 論語 2.15.
  // **靡 already holds なび** (四段カ行 靡く), which this displaces for its 3 VERB
  // tokens, and 三略's 成らざるは靡く、傾かざるは靡し is again the ク活用: **1 edit
  // better on the parser tier**. Neither moves anything else in the corpus.
  罔: { conjClass: "ku-keiyoushi", reading: "な" },
  靡: { conjClass: "ku-keiyoushi", reading: "な" },

  // **固 and 威 were asked the same question and answered no**, and the answer
  // is written here so that it is not asked twice.
  //
  // **固 is ク活用 固し and not the 形容動詞 固なり**, on the corpus's own count.
  // 學則不固 is 學べば則ち固**なら**ず in the received text where this app writes
  // 固**から**ず, and that is what put the question; but over kanbun.info's whole
  // 書き下し文 the ク活用 is what the character overwhelmingly wears — 固く 22,
  // 固からず 6, 固きを 5, 固し 4, 固き 2, 固くして 2 against 固に 7, 固にして 4,
  // 固ならず 2, 固なり 1, 固なれ 1. Entered as `nari-keiyoudoushi` it reads **2
  // edits better on the gold tier and 31 worse on the parser tier**, 42 passages
  // moving, 33 of them the wrong way against 9 the right way. The 兵書 are where the damage is
  // (六韜 +9, 司馬法 +8, 老子 +5), and they are where 固 is a predicate.
  //
  // **威 is not a verb 有り either.** 君子不重則不威 is 威**あら**ず in the received
  // text where this app writes 威**さ**ず, off KANJIDIC2's おど.す. Entered as
  // ラ変 with an `okuriganaPrefix` あ — the noun 威 plus 有り, which is the shape
  // the received 威ありて / 威あらず / 威あるが has — it reads **2 edits better on
  // the gold tier and 33 worse on the parser tier** over 37 passages, 33 of them
  // the wrong way against 4 the right way. The
  // corpus says why: the site writes a bare 威 41 times and 威を 25 against
  // 威あり and its inflections 6 times and 威す 10, so most of what the parser
  // tags VERB the received text reads as the plain noun, and an あり written
  // onto all of them is two characters wrong where 威す was one.
  //
  // Both would need a condition no lemma-keyed entry can carry, and neither is
  // entered.

  // 抵(あ)たる ("to reach, to come up to, to be worth") — 四段ラ行 with an
  // `okuriganaPrefix` た, which is the shape 說's よろこ+ば has and the shape 威
  // just above was refused in. 家書抵萬金 is 家書萬金に**抵たる** in the received
  // reading of 春望, and the app wrote 抵**す**.
  //
  // **KANJIDIC2 gives the character no kun'yomi at all** — テイ and an empty kun
  // list, the same silence 封 below has — so 抵 fell to the generic on'yomi rule
  // and conjugated as サ変 抵す off its only on'yomi. `curatedWordOffKunList`
  // (`reading/kanjidicLookup.ts`) is what carries あ to the page instead, as it
  // does for those five, and here it has nothing to weigh: the question it asks
  // is whether the hand-stated word is absent from the character's kun list, and
  // there is no list.
  //
  // **The prefix is the whole of the entry, and it is what a MISC pin cannot
  // carry.** `Reading=あた|ConjClass=yodan-ra` in a sample's MISC column writes
  // 抵**る** — the whole of あた drawn over the character and the paradigm's own
  // ending beside it — where the received text divides the word 抵(あ)たる, one
  // kana over the character and three beside it. `Okurigana=` states a *fixed*
  // string, which a paradigm then has nothing left to inflect, so the CoNLL-U
  // columns cannot express this division at all and this field is exactly the
  // one that can.
  //
  // **Measured** over kanbun.info's 3,419 passages, against the tree rendered
  // immediately before in the same process. The character is **1 token** there —
  // 傷人及盗抵罪 (故事名言 法三章, parser tier), VERB on `root` — and the prose does
  // not move at all: the site writes 罪に**抵る**, which is one edit from 抵す and
  // one edit from 抵たる alike, so the corpus's only occurrence cannot choose
  // between the two divisions and scores them the same. **The reading ratchet is
  // what chooses.** Its ruby on 抵 is あた, this entry's あ is a prefix of it —
  // which is agreement, the site printing the stem wherever okurigana follows —
  // and the character leaves the disagreement set: **454 characters / 993
  // occurrences -> 453 / 992**.
  //
  // **抵(あた)る, the division the site's own prose writes, was measured beside
  // it** and reads gold 0 / parser **−1**, that one passage and nothing else,
  // with the same ruby gain. It is not taken. The reader has ruled on the
  // division the received 春望 has, one token of a modern okurigana convention is
  // not evidence against it, and the ruby — which is what says the *word* — is
  // indifferent between them.
  抵: { conjClass: "yodan-ra", okuriganaPrefix: "た", reading: "あ" },

  // ---------------------------------------------------------------------------
  // **A VERB whose kun'yomi cannot inflect: five characters kanbun reads
  // on'yomi.**
  //
  // KANJIDIC2 gives each of these either no kun'yomi at all (封), an *undotted*
  // one (敏 さとい, 案 つくえ), or a dotted kun belonging to another word (瞽
  // めし.い, 投 な.げる). An undotted kun is a noun as far as the paradigm rules
  // are concerned — no okurigana to inflect and no class to inflect it by — so a
  // token tagged VERB or ADJ printed the bare character with nothing after it:
  // 事に敏、 for 事に敏にして, 臣、孫子を案こと for 臣案ずるに.
  //
  // **The class is not a rule and must not become one.** "A VERB whose every
  // KANJIDIC2 kun is undotted" is 4,120 tokens over 525 characters, and writing
  // と+サ変 onto all of them read +21 gold / +442 parser worse — the measurement
  // is kept at 主 and 友 above. These five are named one at a time on the site's
  // own ruby, exactly as the ten "wrong kun" entries above are.
  //
  // **Each is a 漢語 read on'yomi, so `curatedWordOffKunList` is what carries the
  // reading to the page and `curatedOnyomiWord` is what keeps the transitivity
  // vote off it** (both in `reading/kanjidicLookup.ts`; 損 and 怯 above reach the
  // page the same way). The second matters for 投 and 瞽, whose kun *are* dotted
  // and would otherwise be graded against each other by the vote, and it is why
  // every reading below is spelled as KANJIDIC2's own on'yomi is: that function
  // compares the two directly. **Nothing here wants `soleKun`**, which narrows
  // the *dotted kun list* to the ones spelling the entry's own word — an on'yomi
  // spells none of them, so the narrowing would find nothing and hand the list
  // back unchanged.
  //
  // **And each states a `conjClass`, because a reading alone does not reach the
  // page at all.** The branch in `readingResolver.ts` that writes a curated
  // word's furigana asks for `reading` and `conjClass` together, the furigana
  // being written beside the paradigm's 終止形 seed — so 瞽 entered as a bare
  // `{ reading: "こ" }` measured **nothing**: no passage moved and the reading
  // ratchet did not shift a character.
  //
  // **Measured together** over kanbun.info's 3,419 passages, against the tree
  // rendered immediately before in the same process: **1 edit better on the gold
  // tier and 8 better on the parser tier**, and the reading ratchet moves
  // **458 characters / 1,042 occurrences -> 454 / 993**, 敏 12, 瞽 16, 封 10 and
  // 投 11 all going to zero. Each entry below carries its own half of that.
  // ---------------------------------------------------------------------------

  // 敏なり ("quick, diligent") — ナリ活用形容動詞, the same shape 仁 and 賢 have.
  // The site glosses 敏 びん **12** times out of 12 and さと not once.
  // 敏於事而愼於言 is 事に敏にして言に慎み; 君子欲訥於言而敏於行 行いに敏ならんと
  // 欲す; 敏而好學 敏にして学を好み; 敏則有功 敏なれば則ち功有り; 雖不敏
  // 不敏なりと雖も.
  //
  // KANJIDIC2's sole kun is さとい, undotted, so the app held a nominal stem and
  // no paradigm and wrote the bare character wherever a form was called for.
  // **2 edits better on the gold tier and level on the parser tier**, six
  // passages moving: 論語 4.24 −1, 17.6 −2 and 堯曰 20.1 −2 the right way,
  // against 論語 7.19 +1 — an ADV 敏 taking the 連用形 に the received text
  // writes without — and the two 不敏 (大學 序 +1, 司馬法 +1), which are the
  // plain noun and take no ending.
  敏: { conjClass: "nari-keiyoudoushi", reading: "びん" },

  // 瞽なり ("blind") — ナリ活用形容動詞. The site glosses 瞽 こ **16** times out
  // of 16 and めし not once. 未見顏色而言謂之瞽 is 之を瞽と謂う;
  // 冕衣裳者與瞽者 瞽者とを見れば.
  //
  // KANJIDIC2's kun is めし.い, the modern 盲い, and the app drew 瞽(めしひ)し —
  // a word of the modern language over a character the received text reads こ
  // throughout.
  //
  // **It costs one edit and is entered all the same, on the reader's rule that
  // the ruby is the authority for readings.** Every 瞽 in the corpus is either
  // 瞽者 — a lexicalized こしゃ the site writes with no okurigana at all — or the
  // bare predicate noun of 之を瞽と謂う, so the なり this writes is one character
  // the received text does not have: 論語 16.6 reads **1 edit worse on the gold
  // tier** (之に瞽しを謂ふ -> 之に瞽なるを謂ふ) and nothing else moves either
  // way. Against that one edit the reading ratchet loses a whole character, 16
  // glossed occurrences that read めしひ and now read こ.
  瞽: { conjClass: "nari-keiyoudoushi", reading: "こ" },

  // 投ず ("to throw, to cast [into]") — 下二段ザ行, and **the class is one cell
  // short of the word, which is worth saying plainly.** A 一字漢語 predicated
  // with a voiced す is ザ行変格活用 — 投ぜ / 投**じ** / 投ず / 投ずる / 投ずれ /
  // 投ぜよ — and `classicalConjugation.ts` has no `za-hen` row; `shimo-nidan-za`
  // (混ず) is the nearest it holds and differs from ザ変 in the 連用形 alone,
  // writing ぜ where the received text writes じ (之を亡地に投**じ**て, 弟の象を
  // 封**じ**て). The other five cells are exact, which is where every edit
  // measured below comes from, and the 連用形 is no worse than what stood before
  // — サ変 wrote 封**し**て, one kana off in the same slot. Adding the row is a
  // change to the conjugation tables and their cartouche census rather than to
  // this one, and is left for the reader to sanction. The site glosses 投
  // とう **11** times out of 11 and な not once. 無所投其角 is
  // 其の角を投ずる所無く; 如以碬投卵者 碬を以て卵に投ずるが如く; 投之於險
  // 之を険に投ず; 設伏投機 伏を設け機に投ぜば; 一人投命 一人、命を投ぜば.
  //
  // KANJIDIC2 has な.げる and -な.げ, the modern 投げる, and the app wrote
  // 投(な)ぐる. **5 edits better on the parser tier** (老子 50, 孫子 5 and 11,
  // 六韜 31, 三略 1) and nothing on the gold tier, which holds no 投 at all.
  //
  // **とう, which is already the historical spelling — たう would be wrong.**
  // An earlier note here had it the other way round, calling タウ this
  // character's historical on'yomi and the index's silence a gap to be worked
  // around. It is not a gap. 投 is 度侯切, 侯韻, 流摂, and the 流摂 finals give
  // トウ in 歴史的仮名遣い; it is the 效摂 (豪/肴) that gives -アウ, which is why
  // the index carries 刀 たう, 高 かう and 道 だう and carries nothing for 投.
  // 頭 settles it: the same 度侯切 rime, and its index entry spells こうべ as
  // かうべ and ず as づ while leaving とう alone. So `candidateReadings` offering
  // とう and only とう is the index being right rather than incomplete.
  投: { conjClass: "za-hen", reading: "とう" },

  // 封ず ("to enfeoff, to invest with a fief") — 下二段ザ行 on 投's reasoning
  // above, its 連用形 shortfall included, and **two things
  // were wrong here and not one**: the app wrote 封(ふう)す where the received
  // text reads 封(ほう)ず. The site glosses 封 ほう **10** times out of 10 and
  // ふう not once. 封弟象爲諸侯 is 弟の象を封じて諸侯と為す; 封昆弟 昆弟を封ず;
  // 非忘封之也 之を封ずることを忘れたるに非ず; 封子萬家 子を万家に封ぜん;
  // 封其後於宋 其の後を宋に封ぜり.
  //
  // 封 is the one character in this group KANJIDIC2 gives **no kun'yomi at
  // all**, so it already fell to the generic on'yomi rule and already
  // conjugated — as サ変 封す, off the first of its two on'yomi. The two halves
  // were measured apart. The reading alone (サ変 ほう) moves the prose **not at
  // all**, the 書き下し文 keeping the kanji and showing no furigana, and takes
  // the character off the reading ratchet by itself; the class with it reads
  // **1 edit better on the parser tier** (史記 50). ふう is the 呉音, the reading
  // of 封建 and 封鎖; ほう is what the fief sense wears.
  封: { conjClass: "za-hen", reading: "ほう" },

  // 案ず ("to consider, to look into") — 下二段ザ行, the same shape 投 has, and
  // with the same 連用形 shortfall that entry sets out. The
  // site glosses 案 あん **8** times out of 8. 案左氏説 is 左氏の説を案ずるに;
  // 臣案孫子有曰 臣案ずるに、孫子に曰えること有り.
  //
  // KANJIDIC2's sole kun is つくえ, undotted — the desk, the character's other
  // and older word — so a VERB 案 printed the bare character: 臣、孫子を案こと.
  // **2 edits better on the parser tier** (李衛公問対 11 and 13, the corpus's
  // only two verbal 案) and nothing on the gold tier.
  //
  // The reading ratchet does not move for it, and that is the instrument's
  // stated limit rather than a null result: it counts a character wrong only
  // where *nothing* we read for it anywhere matches, and the NOUN 案 was
  // reading あん all along.
  案: { conjClass: "za-hen", reading: "あん" },

  // **道 is not entered, and the reason is that nothing in the tree can say
  // which word it is.**
  //
  // 論語 學而 5, 道千乘之國, is the passage this was raised on: the app writes
  // 千乘の國を道、 with no ending at all, KANJIDIC2 giving 道 only the undotted
  // みち and いう. The received reading is 千乗の国を**道(おさ)むる**には.
  //
  // **と+サ変 is the wrong cure and is not to be tried again.** The site's ruby
  // on 道 is みち 257, どう 55, い 9, みちび 6, おさ 1 — never と — and 道 was
  // the single worst character (+22) of the general bare-nominal-VERB rule
  // measured at 主 and 友 above.
  //
  // **The right cure is a word, and it is three words.** Of the seven genuinely
  // verbal 道 in kanbun.info's own passages, three are いふ (夫子自ら道うなり
  // 論語 14.30, 人の善を道うを楽しみ 16.5, 之を失うを道う 大學 10), three are
  // みちびく (之を道くに政を以てし 論語 2.3, twice; 之を道けば斯に行き 19.25)
  // and one is をさむ (學而 5). **Nothing in the tree separates them**: all seven
  // carry the one xpos `v,動詞,行為,伝達`, and a 之 object stands over two of the
  // みちびく and over the 善道 the site reads as a compound alike.
  //
  // So each of the three was entered alone and measured over the whole corpus,
  // against the tree rendered immediately before in the same process:
  // **四段ハ行 い −1 gold / +10 parser**, **四段カ行 みちび +1 / +12**,
  // **下二段マ行 をさ +3 / +14**. The reading ratchet moves for none of them, the
  // NOUN 道 already reading みち, which is what the site prints 257 times.
  //
  // The parser tier is where the damage is, and it says why: 道 is 336 tokens in
  // the corpus and 21 of them are tagged VERB, most of those the plain noun
  // mis-tagged — 不道, 道之爲物, 故道大, 父子之道, 險道, 道德 — and a lemma-keyed
  // entry writes an ending onto every one. That is a mis-annotation and not this
  // table's to compensate for. Until something can tell the three words apart,
  // 道 keeps the bare character.

  // **欲す (サ変, ほつ) — the desiderative read as the verb it is.**
  //
  // The received text reads 欲 as a verb and is unanimous about it:
  // kanbun.info's ruby is **ほっ 180 against よく 16**,
  // `tests/keptCharacters.test.ts` carries the okurigana counts (欲する 7,
  // 欲す 6, 欲すれば 6, of 40), and of the **198** 欲 in the site's own
  // 書き下し文 not one is まほし. This app wrote まほし for all 198 — the
  // `DESIDERATIVE` ending `AUXILIARY_LEMMAS` gives the lemma — so 吾不欲觀之矣
  // came out 吾之を觀る**まほし**ず against a received 吾之を観るを欲せず.
  //
  // **The entry could not be heard until the auxiliary stood down.**
  // `auxiliaryFormFor` is asked *before* the lexicon branch in both panels and
  // answers on the lemma alone, so this entry on its own measured **0 on the
  // gold tier, 0 on the parser tier and 0 on the reading ratchet** — the
  // auxiliary had already spoken for every 欲 there is. That is the same shape
  // `beatsLexicon` answers in `overrides.json` (卒, 與, 更), one branch further
  // up: there the lexicon outranks the resolver and here an auxiliary outranked
  // the lexicon. The stand-down is `PINNED_ONLY_AUXILIARY_LEMMAS` in
  // `conjugationContext.ts`, which is 能's own shape — the `AUXILIARY_LEMMAS`
  // entry kept so that a reader can still pin まほし on a particular 欲, and
  // honoured only where they have. Deleting the character from that table
  // instead would take まほし out of the app entirely, 欲 being its only
  // `DESIDERATIVE`.
  //
  // **Measured with the stand-down, on the branch as found and in one process**
  // over kanbun.info's 3,419 passages: **gold −50 / parser −211** (10,350 →
  // 10,300 and 66,666 → 66,455), 131 passages closer and 4 further, of which
  // **one** is gold (論語 14.2). 吾不欲觀之矣 goes from 吾之を觀る**まほし**ず to
  // 吾之を觀る**欲せず** against a received 吾之を観るを欲せず, and 子貢欲去
  // 告朔之餼羊 reads 去なんと**欲す** — that ん is a second rule,
  // `isDesiderativeComplement`, measured beside this one and reported at
  // `PINNED_ONLY_AUXILIARY_LEMMAS`. The reading ratchet does not move: the
  // resolver has answered ほつす off `overrides.json` all along, and that
  // instrument asks the resolver rather than the panels, which is exactly why a
  // defect this size was invisible to it.
  //
  // **サ変 and not 四段ラ行**, which is what `derivedData` offers (ほ, 欲る):
  // the classical word is ほっす, 未然 ほつせ / 連用 ほつし / 終止 ほつす / 連体
  // ほつする / 已然 ほつすれ, and サ変 is the paradigm that writes all five. The
  // reading is spelled **ほつ** because 歴史的仮名遣い has no small っ — the same
  // respelling `overrides.json`'s own 欲 entry records, and that entry (reading
  // ほつす, undivided) is left exactly as it stands: it answers the *resolver*,
  // which is what the reading ratchet asks, while this answers the panels.
  欲: { conjClass: "sa-hen", reading: "ほつ" },
};

/** Which lemmas the table above states **by hand** — the entry's provenance,
 * which is a different fact from what the entry says and the one a caller
 * needs when it has to weigh an entry against evidence of another kind.
 *
 * A `RESIDUAL` entry is a reading of kanbun the reader settled, each one
 * written down with the words it was settled on; a `derivedData` entry is
 * Wiktionary's leading modern sense for the character, arrived at
 * mechanically and right most of the time. The two look identical from the
 * outside — both are a `LexiconEntry` under a kanji — and the difference
 * decides at least one question that `VERB_LEXICON` alone cannot answer: see
 * `pickKun` in `reading/kanjidicLookup.ts`, where the dictionary's
 * transitivity vote yields to the first kind and not to the second, and where
 * the measurement for both halves of that is written out.
 *
 * Keys, not entries: a caller asking this is asking where the answer it
 * already has came from, and `VERB_LEXICON[lemma]` is by construction the
 * `RESIDUAL` entry wherever this set holds the lemma. */
export const RESIDUAL_LEMMAS: ReadonlySet<string> = new Set(Object.keys(RESIDUAL));

const derived = derivedData as Record<string, LexiconEntry[]>;

/** Every classical sense the build script could classify for a kanji, in
 * confidence order — one kanji routinely spells two different words, and the
 * pair this app has to choose between at render time is the transitive/
 * intransitive one (肥 is こやす 四段サ行 when it has an object and こゆ
 * ヤ行下二段 when it doesn't). See the build script's own doc for how the
 * senses are derived and why the first one is the first one.
 *
 * RESIDUAL goes in front of a kanji's derived senses rather than replacing
 * them, for exactly the reason it wins in `VERB_LEXICON` below: its entries
 * correct a *misidentified sense*, and a misidentified sense is still a real
 * word the resolver may legitimately land on by its own reading (説's derived
 * 説く "to explain" is wrong for the よろこばし this app needs and right for
 * anything that actually reads と). Keeping both leaves the hand-supplied
 * answer first, where every existing caller sees it, without discarding
 * Wiktionary's. */
export const LEXICON_SENSES: Record<string, readonly LexiconEntry[]> = (() => {
  const senses: Record<string, LexiconEntry[]> = {};
  for (const [kanji, list] of Object.entries(derived)) senses[kanji] = [...list];
  for (const [kanji, entry] of Object.entries(RESIDUAL)) senses[kanji] = [entry, ...(senses[kanji] ?? [])];
  return senses;
})();

// RESIDUAL wins where both exist — every entry in it is there specifically
// because the build script's derived answer for that kanji (説/說's only
// modern entry is 説く "to explain", a same-spelling different-sense
// homograph of the よろこばし this app needs) is for the wrong word, not
// because it's merely uncertain. This is the opposite merge order from
// historical-kana's index (a hand table was tried *in front of* that
// general index and reverted — see readingResolver.ts): there, every
// kanji the general index covered had a genuinely correct answer already;
// here, `derived`'s coverage of these specific kanji is a false positive
// on an unrelated sense, not a lower-confidence version of the right one.
//
// Derived from `LEXICON_SENSES` rather than merged a second time, so the
// single-entry view and the full list can't drift: this is by construction
// each kanji's leading sense, which is the entry this table held back when
// the index carried one sense per kanji and nothing else.
export const VERB_LEXICON: Record<string, LexiconEntry> = Object.fromEntries(
  Object.entries(LEXICON_SENSES).map(([kanji, senses]) => [kanji, senses[0]]),
);

/** The senses of `lemma` whose own `reading` is `reading` — the by-reading
 * lookup a context-chosen reading needs, since it has already decided *which*
 * of a character's words is being read and only wants that one's conjugation
 * data back. Returns every match rather than one: a reading does not always
 * pick out a single sense (肥's こやす and こゆ are both こ, differing only in
 * their okurigana), and it is the caller that holds the further evidence to
 * separate them — see `syntheticLexiconEntry` in conjugationContext.ts.
 *
 * Empty for an unknown lemma or an absent reading, so a caller can treat "no
 * attested sense" and "no such kanji" identically; both mean the same thing
 * to it. */
export function lexiconSensesByReading(lemma: string, reading: string | undefined): readonly LexiconEntry[] {
  if (reading === undefined) return [];
  return (LEXICON_SENSES[lemma] ?? []).filter((sense) => sense.reading === reading);
}

/** The modern okurigana a classical paradigm surfaces as, which is the
 * spelling KANJIDIC2 is written in — the inverse of the modern-to-classical
 * derivation `reading/classicalEnding.ts` performs, and the thing that lets an
 * attested sense be checked against a reading taken off a kanjidic entry.
 *
 * Every regular family collapses the same way it historically did: 四段
 * became 五段 with its 終止形 intact (は行's ふ alone modernizing to う, 習ふ
 * -> 習う), and both 二段 families became 一段, keeping their mizen vowel and
 * taking る (肥ゆ's え -> 肥える, 立つ's て -> 立てる, 起く's き -> 起きる).
 * The irregulars all ended up in -る too (見る, 来る, 有る), except ナ変's 死ぬ.
 * 形容動詞 have no okurigana of this kind at all and return undefined.
 *
 * That the 二段 families gain a る here is what makes this direction — and not
 * the 終止形, which they share with 四段 of the same 行 — the one that
 * identifies a word: 立つ and 立てる are both 立 + つ in classical, and only
 * the modern spelling keeps them apart.
 *
 * Where this guesses wrong it fails *closed* — a sense whose modern spelling
 * doesn't match is simply not taken, leaving the caller exactly where it was
 * without one — which is why サ変 is given the する that covers 爲/為 rather
 * than the す that would also fit 為す. */
export function modernOkurigana(sense: LexiconEntry): string | undefined {
  const conjClass = sense.conjClass;
  if (!conjClass) return undefined;
  const prefix = sense.okuriganaPrefix ?? "";
  if (conjClass === "ku-keiyoushi") return modernKana(prefix + "い");
  if (conjClass === "shiku-keiyoushi") return modernKana(prefix + "しい");
  if (conjClass === "nari-keiyoudoushi" || conjClass === "tari-keiyoudoushi") return undefined;
  if (conjClass.startsWith("kami-nidan-") || conjClass.startsWith("shimo-nidan-")) {
    return modernKana(prefix + conjugate(conjClass, "mizen") + "る");
  }
  if (conjClass.startsWith("yodan-")) return modernKana(prefix + conjugate(conjClass, "shuushi"));
  if (conjClass === "na-hen") return modernKana(prefix + "ぬ");
  return modernKana(prefix + "る");
}

/** The modern dictionary reading a classical word surfaces as, given its
 * paradigm and its own classical citation reading — `modernOkurigana` above
 * carried one mora further, from the ending to the whole headword.
 *
 * What it is for: a dictionary that holds classical words holds them under
 * their *classical* headword (JMdict lists 答ふ, こたう) while KANJIDIC2 holds
 * the same word under its modern one (答's こた.える). Neither can be looked up
 * in the other until one of them is converted, and this is the direction that
 * converts — the same many-to-one direction `modernKana` below is safe in, and
 * for the same reason (see its doc). The reverse, modern to classical, is the
 * one-to-many guess this whole file exists to avoid making.
 *
 * `classical` is the classical citation reading **as a modern dictionary
 * spells it**, which is what JMdict's own reading field holds: 答ふ is written
 * こたう there, not こたふ. So the ending stripped off it is
 * `modernKana(conjugate(conjClass, "shuushi"))` and not the 終止形 itself.
 * Returns undefined where `classical` does not end in that ending at all —
 * the paradigm and the reading are then not about the same word, and nothing
 * can be said.
 *
 * The stem this leaves is the kanji's own reading (こた), so the result is the
 * modern headword's reading (こたえる) — exactly the string a KANJIDIC2
 * kun'yomi's reading and okurigana make when joined. See
 * `classicalParadigmByModernReading` in `reading/jmdictLookup.ts`, which is
 * the one caller and which uses it to key an index. */
export function modernisedCitation(conjClass: ConjClass, classical: string): string | undefined {
  const okurigana = modernOkurigana({ conjClass });
  if (okurigana === undefined) return undefined;
  const shuushi = modernKana(conjugate(conjClass, "shuushi"));
  if (!classical.endsWith(shuushi)) return undefined;
  return classical.slice(0, classical.length - shuushi.length) + okurigana;
}

/** 歴史的仮名遣い to 現代仮名遣い, for okurigana only.
 *
 * The lexicon is written historically throughout and KANJIDIC2 is written
 * modernly, so the two spellings have to be brought into one before they can
 * be compared at all. Everything in an okurigana is word-*medial* by
 * construction — the kanji is in front of it — which is exactly the position
 * the three regular mergers apply in, and which is why this is a fixed table
 * rather than the undecidable modern-to-historical direction
 * `classicalConjugation.ts` warns about (that direction is one-to-many; this
 * one is many-to-one, and only ever run forwards).
 *
 *  - ハ行転呼: medial は行 became わ行/あ行 (習ふ -> 習う, 与へる -> 与える,
 *    変はる -> 変わる, 生ひる -> 生いる);
 *  - ワ行: ゐ/ゑ/を merged into い/え/お (用ゐる -> 用いる, 植ゑる -> 植える);
 *  - 四つ仮名: ぢ/づ merged into じ/ず (恥ぢる -> 恥じる).
 *
 * Without this the three rows added with `EXTRA_SUFFIX_OF` could never match
 * anything: ワ行下二段's own mizen ゑ built 植ゑる where KANJIDIC2 has 植える,
 * so 王植樹 went on reading the modern 植える even with 植う in the lexicon. */
function modernKana(okurigana: string): string {
  return [...okurigana].map((kana) => MEDIAL_KANA_MERGERS[kana] ?? kana).join("");
}

/** The same fold for a *reading*, which differs from an okurigana in exactly
 * one place: its first kana is word-initial, and ハ行転呼 is a word-*medial*
 * change. 早 はや and 舟 ふね keep their は行 initial; 貯 たくは becomes たくわ,
 * 帰 かへ becomes かえ, 沈 しづ becomes しず.
 *
 * The same rule, and the same exemption, `historicalKana.ts`'s own `modernKana`
 * applies when it keys an attestation by what a modern dictionary would call it
 * — written again here rather than imported so this file stays a leaf (its only
 * imports are `classicalConjugation.ts` and the generated index, which is what
 * lets `reading/classicalEnding.ts` import *it* without closing a cycle).
 *
 * Used for one thing: comparing a lexicon reading, which is historical, against
 * a reading that is modern — see `attestedSenseByModernSpelling`. It is
 * many-to-one and imperfect in that direction (続's つづ folds to つず where
 * modern spelling keeps つづく), and that costs nothing here, because a fold
 * that lands on a string no dictionary or menu ever produces simply matches no
 * query. What it must not do is *lose* an answer by turning one match into two,
 * and it does not: measured over the whole shipped index, no lemma has two
 * senses that collide only after folding. */
export function modernReading(reading: string): string {
  return [...reading].map((kana, i) => (i === 0 ? kana : MEDIAL_KANA_MERGERS[kana] ?? kana)).join("");
}

const MEDIAL_KANA_MERGERS: Record<string, string> = {
  は: "わ", ひ: "い", ふ: "う", へ: "え", ほ: "お",
  ゐ: "い", ゑ: "え", を: "お",
  ぢ: "じ", づ: "ず",
};

/** The one sense of `lemma` that a *modern* citation spelling identifies —
 * reading plus the okurigana KANJIDIC2 writes after it — or undefined where
 * the lexicon's data does not settle the question.
 *
 * Both halves are needed and neither is enough. A reading alone is a stem,
 * and a stem is shared by words that are not the same word (悔 read く is
 * 悔いる to KANJIDIC2 and 悔む to Wiktionary; 見 read み is 見る, 見す and 見ゆ
 * all three). The okurigana alone says nothing about which character it
 * follows. Together they are the modern dictionary headword, which is exactly
 * what `pickKun`/`pickByTransitivity` had in hand when they chose it.
 *
 * More than one surviving candidate means the evidence does not identify the
 * word, so nothing is claimed — 射's 射る is attested both 上一段 and 四段ラ行
 * with the same reading い, and both spell themselves 射る today.
 *
 * **Both halves are compared modernly, and the reading half was not.** The
 * okurigana has gone through `modernKana` since this function existed — that is
 * what `modernOkurigana` is — while the reading was matched against the
 * lexicon's own spelling, which is 歴史的仮名遣い throughout. For most words the
 * two coincide and the omission was invisible; where they do not, this function
 * answered nothing about a word it holds. 貯 is the case that showed it: its
 * sense is `たくは` + ハ行下二段, whose modern citation spelling is たくわえる
 * exactly, and a reader who picked KANJIDIC2's own たくわ.える off the furigana
 * menu was asking about that very word under that very spelling and being told
 * the lexicon knew of none — so the pick kept the あ-row ending `chosenConjClass`
 * can state no paradigm for, and 甕中貯水 printed the modern 貯える.
 *
 * `lexiconSensesByReading` is deliberately left alone: it is asked elsewhere
 * with a *classical* reading the resolver has already settled (see
 * `attestedSense` in conjugationContext.ts), where an exact match is the
 * question. This is the modern-spelling lookup, and the fold belongs to it. */
export function attestedSenseByModernSpelling(
  lemma: string,
  reading: string | undefined,
  okurigana: string | undefined,
): LexiconEntry | undefined {
  if (reading === undefined) return undefined;
  const matches = (LEXICON_SENSES[lemma] ?? []).filter(
    (sense) =>
      sense.reading !== undefined &&
      (sense.reading === reading || modernReading(sense.reading) === reading) &&
      modernOkurigana(sense) === okurigana,
  );
  return matches.length === 1 ? matches[0] : undefined;
}
